    bag_examples_v2_toast: "🎁 আপনার ব্যাগে নতুন উদাহরণ: উপহারের আইডিয়া, হোটেলের তালিকা আর ফ্লাইটের তালিকা ✨",
    faq_a_bag_examples_list: "নতুন ব্যাগে কিছু উদাহরণ থাকে, যা অন্য সবকিছুর মতোই বদলানো বা মুছে ফেলা যায়: বাড়ি (বাজার, রেসিপি, এই সপ্তাহের খাবার), পরিবার (ছোট ছোট মুহূর্ত, জন্মদিনের পার্টির তালিকা, কার্যক্রম আর ক্লাস), আইডিয়া (সপ্তাহান্তের আইডিয়া, বিভাগ অনুযায়ী উপহারের আইডিয়া, আর জমানো টাকা দিয়ে কী করবেন) আর ভ্রমণ (যেসব জায়গায় যেতে চান, ভ্রমণের জিনিসপত্র, হোটেলের জিনিসপত্র আর বিদেশে ফ্লাইটের তালিকা)। আগে থেকে থাকা ব্যাগ সবচেয়ে নতুনগুলো একবার পায়, নিজের পকেটগুলোর ভেতরে।",
    faq_q_bag_examples_list: "আমার ব্যাগে কী কী উদাহরণ থাকে?",
    faq_a_nm_me1_guide: "Sky – New Me-তে আপনার চরিত্র, তার প্রথম রূপে (Sky 1)। প্রথমবার, যোগ দেওয়ার ঠিক পরেই, চারদিকে ঝিকিমিকি ছড়িয়ে আলোর একটি পোর্টাল খুলে যায় আর তার ভেতর থেকে Sky উড়ে বেরিয়ে আসে, কয়েকটি ট্যাপে জানিয়ে দেয় সামনে কী আছে, তারপর প্রতিটি প্রশ্নের পাশে থাকে: খাবার বাছাইয়ের সময় সে আপনার সাথে নিজের বইয়ে লেখে, আর তার পরামর্শে ট্যাপ করলে আরেকটি দেখা যায়। শেষে Sky আপনার সাথে উদযাপন করে এবং একটি ছোট ট্যুরে নিয়ে যায় – আর ট্যুর শেষ হলে, আপনার সাথে তার আরও একটি ছোট্ট মুহূর্ত থাকে। মাঝপথে – প্রশ্নের সময় বা ট্যুরের সময় – বেরিয়ে গেলে, পরের বার Sky আপনাকে দেখে খুশি হয় আর জিজ্ঞেস করে একই জায়গা থেকে চালিয়ে যাবেন কি না।",
    faq_q_nm_me1_guide: "New Me-তে ঢোকার পথ কে দেখায়?",
