    nm_m1_tip_rice: "আমি সবচেয়ে বেশি ভালোবাসি ভাত – এটাই হবে আমার ভিত্তি, তাই এটাই বেছে নেব। আমার পরামর্শ, চেনা আর সুস্বাদু খাবারই বেছে নিন।",
    faq_a_shop_basics: "কেনাকাটার তালিকা যখন একেবারে খালি থাকে – যেমন একদম শুরুতে – তখন শুরুর জন্য একটি মৌলিক তালিকা দেখা যায়: দুধ, পাউরুটি, ডিম আর আরও অনেক কিছু। কোনো জিনিসে ট্যাপ করলে সেটি তালিকায় যোগ হয়, আর “সব যোগ করুন” সবকিছু একসাথে যোগ করে। তালিকায় কিছু এলেই মৌলিক তালিকাটি অদৃশ্য হয়ে যায়।",
