    room_genie_rest: "বনের আত্মা এখন বিশ্রাম নিচ্ছে – কাল আবার আসুন ✨",
    faq_a_shop_holidays: "কেনাকাটার তালিকায় উপহারে ট্যাপ করুন: আপনার দেশের (যা সেটিংসে বেছে নেওয়া আছে) উৎসবগুলো তারিখসহ ক্রমানুসারে দেখা যায় – তারিখগুলো প্রতি বছর নিজে থেকেই হিসাব হয়। কোনো উৎসবে ট্যাপ করলে সেই উৎসবে লোকে যা কেনে তার একটি তৈরি তালিকা খোলে; সব কিছু আগে থেকেই বাছাই করা থাকে (যা আগে থেকেই আপনার তালিকায় আছে তা ছাড়া), যা দরকার নেই তার টিক তুলে দিন আর “তালিকায় যোগ করুন”-এ ট্যাপ করুন। উৎসবের দুই সপ্তাহ আগে তালিকার ওপরে একটি ছোট কার্ড দেখা যায়; ✕ সেটিকে পরের উৎসব পর্যন্ত লুকিয়ে রাখে।",
    faq_q_shop_holidays: "“উৎসবে কী কিনবেন” কীভাবে কাজ করে?",
    shop_hol_add: "তালিকায় যোগ করুন ({n})",
    shop_hol_added: "তালিকায় যোগ হয়েছে: {n}",
    shop_hol_btn: "উৎসবে কী কিনবেন",
    shop_hol_items_title: "{holiday} – কী কিনবেন?",
    shop_hol_not_now: "এখন নয়",
    faq_a_shop_delivery: "কেনাকাটার তালিকায় ট্রাকে ট্যাপ করুন: ডেলিভারিতে কী আছে (সব আগে থেকেই বাছাই করা থাকে), কবে পৌঁছাবে – আজ, আগামীকাল বা অন্য দিন – আর কোন সময়ে (সকাল, দুপুর, সন্ধ্যা, বা নিজের সময় বেছে নিতে “অন্যান্য…”), তা বেছে নিন। জিনিসগুলো দিন আর সময়সহ তালিকার ওপরে “পথে আছে” কার্ডে চলে যায়। সেই দিন এলে আমার দিন-এ “ডেলিভারি কি পৌঁছেছে?” দেখা যায় (আর কার্ডে থাকে “পৌঁছেছে?”)। সব পৌঁছালে সেগুলো “আবার কিনুন”-এ চলে যায়। কিছু কম থাকলে যা পৌঁছায়নি তাতে ট্যাপ করুন – সেটি সরাসরি তালিকায় ফিরে আসে।",
    faq_a_shop_departments: "তালিকাটি নিজে থেকেই সুপারমার্কেটের বিভাগ অনুযায়ী সাজে – ফল ও সবজি, রুটি, দুগ্ধজাত ও ডিম, মাংস ও মাছ, মুদি, হিমায়িত, পানীয়, স্ন্যাকস, পরিষ্কার, ব্যক্তিগত যত্ন, শিশু ও পোষা প্রাণী – যাতে আপনি তাকের সারিগুলো ক্রমানুসারে ঘুরে আসতে পারেন। বিভাগটি জিনিসের নাম থেকে চেনা হয়। কোনো জিনিস ভুল জায়গায় গেলে সেটিতে ট্যাপ করে তার বিভাগ বেছে নিন, অথবা নিজের মতো লিখতে “অন্যান্য…” বেছে নিন।",
    faq_a_shop_share_qty: "হ্যাঁ। প্রতিটি জিনিসের পাশে + আরও একটি যোগ করে (×2, ×3…) আর − একটি কমায়। কেনাকাটার তালিকার ওপরের শেয়ার বোতাম পুরো তালিকাটি, বিভাগ অনুযায়ী সুন্দর করে সাজিয়ে, WhatsApp, ইমেইল বা কপি হিসেবে পাঠায়।",
    faq_a_shop_two_buttons: "দুটোরই মানে “কেনা হয়েছে”। ✕ সেই জিনিসের জন্য যা আপনি একবারই কেনেন – এটি তালিকা থেকে সরে যায় (আর ভুল হলে কাজে লাগার জন্য 🗑️ আর্কাইভে অপেক্ষা করে)। ↺ সেই জিনিসের জন্য যা আপনি বারবার কেনেন – এটি তালিকা থেকে সরে “আবার কিনুন”-এ অপেক্ষা করে: তালিকার একদম নিচে ময়লার ঝুড়ির পাশের ছোট ↺ বোতামটি এটি খোলে, আর সেখানে একবার ট্যাপ করলে কোনো জিনিস আবার তালিকায় ফিরে আসে। এর ভেতরের “সম্পাদনা” থেকে কোনো জিনিস সেখান থেকে সরাতে পারবেন। কোনো জিনিস যোগ করার সময় আগে কেনা জিনিসগুলো পরামর্শ হিসেবে দেখা যায়, আর জিনিসটি যদি আগে থেকেই তালিকায় থাকে, তাহলে দ্বিতীয় লাইন না হয়ে শুধু ×2 হয়ে যায়।",
