    nm_demo_title: "খাবার বদল যেভাবে হয়",
    faq_a_new_me_challenge_journal: "কোনো চ্যালেঞ্জ শেষ হলে – বড়, মিনি বা সপ্তাহের চ্যালেঞ্জ – উদযাপনে একটি 📝 কেমন হলো? বোতাম থাকে। এটি চ্যালেঞ্জের ডায়েরিতে একটি পাতা খোলে: কেমন লাগল (পাঁচটি মুখ), কী সাহায্য করল, কী কঠিন ছিল আর এখান থেকে কী সঙ্গে নিয়ে যাব – কোনোটিই বাধ্যতামূলক নয়, আর পরেও করা যায়। ডায়েরিটি জাদুর ব্যাকপ্যাকের একটি হীরা: শেষ হওয়া প্রতিটি চ্যালেঞ্জ, তার তারিখ আর যা লেখা হয়েছে, সবচেয়ে নতুনটি সবার আগে – পড়তে, বদলাতে বা শেয়ার করতে যেকোনো একটিতে ট্যাপ করুন (শুধু পাতায় যা আছে, সেটুকুই শেয়ার হয়)। শেষ হওয়া চ্যালেঞ্জ অর্জনে “যে চ্যালেঞ্জগুলো শেষ করেছি”-এর নিচে একটি পদকও পায়। চ্যালেঞ্জের ডায়েরি সাধারণ ডায়েরি থেকে আলাদা।",
    faq_q_new_me_challenge_journal: "চ্যালেঞ্জের ডায়েরি কী?",
