    faq_a_ai_reminder_in_text: "হ্যাঁ – কাজের সঙ্গেই লিখে দিন, যেমন “কাল 17:00-এ পার্সেল নিতে যাওয়া, এক ঘণ্টা আগে রিমাইন্ডার সহ”। রিমাইন্ডারটি কাজটিতেই সেভ হয়: এক ঘণ্টা আগে, আধা ঘণ্টা আগে, এক দিন আগে ইত্যাদি, আর সময় ছাড়া “আমাকে মনে করিয়ে দিও” মানে 10 মিনিট আগে। টেক্সটে লেখা রিমাইন্ডার একই উইন্ডোর রিমাইন্ডার ঘরের চেয়ে অগ্রাধিকার পায়।",
