    books_home_chip: "{title} · পৃ. {page}",
    books_home_of: "মোট {total}",
    books_home_off_toast: "বইটি হোম স্ক্রিন থেকে সরে গেছে",
    books_home_on_toast: "বইটি হোম স্ক্রিনে আছে 📖",
    books_home_pin: "হোম স্ক্রিনে",
    books_home_q: "আমি কোন পৃষ্ঠায়?",
    books_home_save: "সংরক্ষণ করুন",
    faq_a_books_home_chip: "হ্যাঁ। পড়ার কোণে, যে বইটি এখন পড়া হচ্ছে তার কার্ডে 📌 হোম স্ক্রিনে ছুঁন। হোম স্ক্রিনে শুভেচ্ছার নিচে বই আর পৃষ্ঠাসহ একটি ছোট বোতাম দেখা যায় – সেটি ছুঁয়ে নতুন পৃষ্ঠার নম্বর লিখে সংরক্ষণ করুন, আর অগ্রগতি নথিভুক্ত হয়ে যায় (পড়ার কোণেও)। আবার 📌 ছুঁলে সেটি সরে যায়। একসঙ্গে কয়েকটি বই থাকতে পারে – প্রতিটির জন্য একটি বোতাম – আর সব ডিভাইসে একই থাকে।",
    faq_a_new_me_week_challenge: "এক সপ্তাহের ছোট চ্যালেঞ্জ, যা আপনি নিজে বেছে নেন। করিডোরে একটি বড় কার্ড আছে: “এই সপ্তাহে কী নিয়ে কাজ করতে চান?” – সেটি ছুঁয়ে একটি ক্ষেত্র বেছে নিন (নিজের সঙ্গে, অন্যদের সঙ্গে, শেখা ও এগিয়ে চলা, প্রশান্তি, সাহসের ছোট পদক্ষেপ, ঘর ও রুটিন) আর একটি চ্যালেঞ্জ, এবং কখন শুরু হবে তা ঠিক করুন। একই চ্যালেঞ্জগুলো চ্যালেঞ্জ স্ক্রিনেও আছে, 🌱 ব্যক্তিগত বিকাশের অধীনে। প্রতিদিন কার্ডে ✓ দিন (সপ্তাহে একটি ছুটির দিন), আর প্রতিটি শেষ হওয়া সপ্তাহ গোপন জগতের জন্য একটি নতুন চাবি আনে। “প্রতিদিন ২ পৃষ্ঠা পড়া” পড়ার কোণে নথিভুক্ত পৃষ্ঠা থেকে নিজে থেকেই টিক হয়ে যায়। সপ্তাহ শেষ হলে “📌 দৈনিক কাজ হিসেবে রেখে দিন” সেটিকে আপনার বেছে নেওয়া সময়ে আমার রুটিনে যোগ করে, প্রতিদিন ✓ সহ। একসঙ্গে সপ্তাহের একটিই চ্যালেঞ্জ চলে; বড় ও ছোট চ্যালেঞ্জগুলো তার পাশাপাশি চলতে থাকে।",
    faq_a_room_genie: "সমুদ্রমুখী বারান্দায় আলাদিনের প্রদীপ ছুঁলে বনের আত্মা বেরিয়ে আসে – আর একটি কথোপকথন শুরু হয়: আপনার ইচ্ছে কী (জীবনে কী বদলাতে চান), সত্যি হলে কেমন লাগবে, পথে কী কঠিন, আর এখনকার পরিস্থিতিকে কীভাবে ভালোর দিকে ঘোরানো যায়। তারপর আনুমানিক কত সময় লাগবে, একটি প্রথম ছোট পদক্ষেপ আর আরও দুটি, আর কঠিন লাগার মুহূর্তের জন্য একটি “যদি… তাহলে…”। শেষে পুরো ইচ্ছেটি ধাপে ধাপে দেখা যায়, আর সেটিকে আমার লক্ষ্যসমূহে লক্ষ্য বানানো যায় (পদক্ষেপগুলো পথের মাইলফলক হয়ে যায়, বেছে নেওয়া সময় অনুযায়ী তারিখসহ; সেখানে সবকিছু বদলানো যায়) অথবা ডায়েরিতে সংরক্ষণ করা যায় – আর তারপর আত্মা বিদায় নেয়। এর কোনোটি না বাছলে কিছুই সংরক্ষিত হয় না। দ্বিতীয়বার থেকে আত্মা আগে জিজ্ঞেস করে, জীবনে আর কিছু বদলাতে চান কি না: হ্যাঁ – একই কথোপকথন; এখন না – আগেই ঠিক করা লক্ষ্যগুলো পূরণ করার একটি অনুস্মারক। আত্মা দিনে একবার বেরিয়ে আসে: একটি ইচ্ছে সংরক্ষিত হলে (বা “এখন না” বেছে নিলে), সে কাল পর্যন্ত বিশ্রাম নেয়। প্রশ্নগুলো ইচ্ছেকে পরিকল্পনায় বদলানোর একটি পরিচিত পদ্ধতি অনুসরণ করে: ইচ্ছে, ফলাফল, বাধা ও পরিকল্পনা।",
    faq_q_books_home_chip: "হোম স্ক্রিনে কি আমার বই আর পৃষ্ঠা দেখা যায়?",
