    nm_me_choose: "বেছে নিন",
    nm_me_on_screen: "স্ক্রিনে",
    faq_a_new_me_game: "New Me-তে খেলার বোতামগুলো সবসময় একই জায়গায় থাকে – করিডোরে, গোপন ঘরে আর বনের সব জায়গায়; শুধু মাঝখানের আঁকা ছবিটা বদলায়। ওপরে: যাত্রার দিন, চাবি, ধারাবাহিকতা আর আজকের শক্তি (পরিকল্পনা থেকে কতটা খাওয়া হয়েছে), আর তার নিচে পরের মিশন – নির্ধারিত সময়ে পরের খাবার (ট্যাপ করলে খোলে, ✓ খেয়েছি-সহ)। এক পাশে: সারা দিন, চ্যালেঞ্জ আর আমার যাত্রা, আর তাদের পাশে সপ্তাহের চ্যালেঞ্জ – তার 7টি দিন আর আজকের জন্য একটি ✓। নিচে: জাদুর ব্যাকপ্যাক (পুরো New Me – জগতের মানচিত্র, আমার যাত্রা, কেনাকাটা, অর্জন, চ্যালেঞ্জের ডায়েরি, শরীরের মাপ, ছবি, মাসিক ক্যালেন্ডার, দৈনিক টেবিল, রিমাইন্ডার, মেনু PDF আর সেটিংস; এটি আলাদা স্ক্রিন হিসেবে খোলে)। ব্যাকপ্যাকের সবার প্রথমে থাকা জগতের মানচিত্রে বনের প্রতিটি জায়গা দেখা যায় – কোনো জায়গায় ট্যাপ করলেই সেখানে যাওয়া যায়; তালাবন্ধ জায়গায় দেখা যায় কয়টা চাবি লাগবে। Sky হলো বনের পথে আপনার চরিত্র: শুরুতে Sky 1, কয়েকটি চ্যালেঞ্জের পর (4টি চাবি) বড় হয়ে Sky 2, আর শেষের দিকে (9টি চাবি) Sky 3 – চোখের সামনে ঘটে যাওয়া এক নতুন রূপে। সব ধাপ দেখতে Sky-তে ট্যাপ করুন – যে ধাপে আগেই পৌঁছানো হয়েছে, সেটি আবার বেছে নেওয়া যায়, তাই আগের ধাপ ফিরে আসতে পারে। Sky ভেসে থাকে – তাকে আঙুল বা মাউস দিয়ে টানা যায়, আর সে যে প্রবেশপথ ছোঁয়, সেটি খুলে যায় (তালাবদ্ধ পথে লেখা থাকে কয়টি চাবি কম)। Sky প্রতিটি ঘরে ও জায়গায়ও সঙ্গে আসে, আর যেখানে রেখে দেন সেখানেই ভেসে থাকে: তাকে যেকোনো জায়গায় টেনে নিন, আর তার নিচের জ্বলজ্বলে বলয়টি টেনে তাকে পুরো ঘুরিয়ে দিন; সে যেদিকে চলে সেদিকেই মুখ করে থাকে (কম্পিউটারে: তীর দিয়ে চলে, Q আর E দিয়ে ঘোরে)। করিডোরে, উপরের বারের নিচের ছোট 🏠 হোম স্ক্রিনে ফিরিয়ে নিয়ে যায়; প্রতিটি ঘরে ও জায়গায়, একই কোণের বোতামটি করিডোরে ফিরিয়ে নিয়ে যায়।",
    faq_q_new_me_game: "খেলার বোতাম, জগতের মানচিত্র আর Sky কীভাবে কাজ করে?",
