    faq_a_new_me_menu_build: "প্রথমে প্রশ্নাবলি জানতে চায় আপনি কোন কোন খাবার কখন খান (২ বেলা খাবার + একটি নাস্তা, ২ বেলা খাবার + হালকা রাতের খাবার, বা দুটোই), আর সন্ধ্যায় কিছু থাকে কি না – খাওয়ার না পান করার, কী, আর কটায়। “২ বেলা খাবার + একটি নাস্তা”-এ খাবার দুটি হলো দুপুরের খাবার (11:30) আর রাতের খাবার (19:00), আর নাস্তা 16:00-এ। তারপর সেই খাবারগুলোর সব বিকল্প দেখা যায়। প্রতিটি খাবারে ২টি পর্যন্ত পছন্দের বেছে নিন – মেনুতে লেখা থাকে “এটা বা ওটা”। কিছু বিকল্পে (পিটা ও স্প্রেড, কর্নফ্লেক্স ও দুধ, হালকা কিছু) পছন্দের ৩টি পর্যন্ত জিনিস বেছে নেওয়া যায়, প্রতিটি তার নিজের পরিমাণে, আর মেনুতে লেখা থাকে “এটা বা ওটা বা ওটা”; ক্যালরি বাছাই অনুযায়ী হয়। কফি আর পানীয়ও একইভাবে কাজ করে। প্রতিটি বাছাই ভারসাম্য করা, তাই দিনের মোট ঠিক 1,300 বা 1,500 হয়। যেকোনো সময় বদলাতে: ⚙️ সেটিংস → 🍽️ আপনার মেনু তৈরি করুন, অথবা খাবারের কার্ডে “পছন্দের ৩টি পর্যন্ত বেছে নিন”।",
