    faq_a_myday_water_toggle: "হ্যাঁ। 'আমার দিন'-এ পানির গ্লাস (আরও এক গ্লাসের জন্য + সহ) ডিফল্টভাবে দেখা যায়। লুকাতে সেটিংস > ব্যক্তিগতকরণ ও ক্যালেন্ডার-এ \"'আমার দিন'-এ পানি দেখান\" বন্ধ করুন। কিছুই মুছে যায় না – পানি পর্যবেক্ষণ চলতে থাকে, আর আবার চালু করলে গ্লাস ফিরে আসে।",
