    faq_a_routine_newme_sync: "New Me থাকলে 'আমার রুটিন'-এর ⚙️-এ 'New Me-এর সঙ্গে সিঙ্ক' সুইচ থাকে। চালু থাকলে (ডিফল্ট) আজকের New Me খাবারগুলো 'আমার দিন' আর 'আমার রুটিন'-এ দেখায় – লুকানো রুটিনের খাবারের জায়গায়। বন্ধ করলে New Me-এর খাবারগুলো দুই জায়গা থেকেই সরে যায় আর রুটিন ঠিক আগের মতো হয়ে যায়। কিছুই মুছে যায় না – আবার চালু করলে সব ফিরে আসে এবং জিজ্ঞেস করে রুটিনের কোন খাবারগুলো লুকাবেন।",
    faq_q_routine_newme_sync: "'আমার রুটিন' ও 'আমার দিন'-এর সঙ্গে New Me-এর সিঙ্ক কীভাবে চালু বা বন্ধ করব?",
