    faq_a_food_list_languages: "বিল্ট-ইন খাবারের তালিকা শুরু হয়েছিল ইসরায়েলি খাবার আর সেগুলোর হিব্রু নাম দিয়ে। অন্য সব ভাষায় প্রতিটি খাবার তার ইংরেজি নামে দেখায়, আর খোঁজ তার জানা যেকোনো ইংরেজি নাম দিয়ে খুঁজে পায় (যেমন 'broth' দিয়ে Clear soup পাওয়া যায়); যেসব খাবারের শুধু হিব্রু নাম আছে সেগুলো সেখানে দেখায় না। তালিকায় যা নেই তা নিজের ভাষায় লিখে দিলেই হবে – AI অনুমান সব ভাষায় কাজ করে।",
    faq_q_food_list_languages: "আমার ভাষায় খাবারের তালিকায় কেন ইংরেজি নাম, আর কম খাবার দেখায়?",
    settings_copyright_line: "© 2026 সর্বস্বত্ব সংরক্ষিত। অ্যাপ তৈরি করেছেন eden zabari।",
    workout_ready_replace_btn: "বদলে দিন",
    faq_a_sport_workout_ai: "\"আমার ওয়ার্কআউট\" → ⋯ → \"AI দিয়ে প্ল্যান\" (আর টেবিল খালি থাকলে তৈরি প্ল্যানের পাশের টাইলেও)। কয়েকটি ট্যাপে উত্তর দিন – সপ্তাহে কতবার, কখন, জায়গা, স্তর ও লক্ষ্য, প্রায় সবগুলোতেই \"অন্যান্য\" আছে – আর চাইলে একটি খোলা লাইন যোগ করুন, যেমন সংবেদনশীল হাঁটু বা গ্রীষ্মের মধ্যে 5 কিমি দৌড়। AI পুরো একটি সপ্তাহ সাজায়: ওয়ার্কআউটের ধরন, দিন, সময়, সময়কাল, তীব্রতা, এক্সারসাইজ ও বিশ্রামের দিন। কিছু সেভ হওয়ার আগে প্রিভিউ আসে: \"আমার টেবিলে রাখুন\" (টেবিলের বদলে বা তার সঙ্গে), \"আরেকটি প্রস্তাব\" (3 বার পর্যন্ত) অথবা \"উত্তর বদলান\"। প্ল্যানটি ইচ্ছে করেই পরিমিত রাখা হয়, আর ব্যথা বা চোটের কথা লিখলে হালকা বিকল্প ও একজন বিশেষজ্ঞের পরামর্শ নেওয়ার কথা আসে। এটি সময়সূচি ও রুটিনের AI-এর একই কোটা ব্যবহার করে: 5 বার বিনামূল্যে, আর প্রিমিয়ামে মাসে 60 বার।",
    faq_q_sport_workout_ai: "AI দিয়ে ওয়ার্কআউট প্ল্যান কীভাবে তৈরি করব?",
