    faq_a_sport_workout_jar: "প্রতিটি ধরনের ওয়ার্কআউটের নিজস্ব রঙের তারা আছে – দৌড় গোলাপি, হাঁটা সবুজ, সাঁতার নীল ইত্যাদি। এই সপ্তাহে লগ করা প্রতিটি ওয়ার্কআউট, টেবিল থেকে বা আলাদাভাবে, তার তারাটি \"আমার ওয়ার্কআউট\"-এর ওপরের বয়ামে ফেলে দেয়, আর বয়ামটি সাপ্তাহিক লক্ষ্য পর্যন্ত ভরে ওঠে (লক্ষ্য বদলাতে এতে ট্যাপ করুন)। লক্ষ্যে পৌঁছালে বয়ামটি ঝলমল করে। পাশের ছোট বয়ামটি গোনে টানা কত সপ্তাহ এটি ভরেছে।",
    faq_q_sport_workout_jar: "\"আমার ওয়ার্কআউট\"-এ রঙিন তারা আর বয়াম কী?",
    faq_a_sport_workout_gcal: "হ্যাঁ – ⋯ → Google ক্যালেন্ডার-এ (সেটিংসে Google ক্যালেন্ডার যুক্ত করার পর)। সময় থাকা প্রতিটি ওয়ার্কআউট তার দিনগুলোতে প্রতি সপ্তাহে পুনরাবৃত্ত একটি ইভেন্ট হয়ে যায়, আর অ্যাপের পরিবর্তন সেখানেও হয়। রিমাইন্ডার শুধু অ্যাপ থেকে আসে, তাই Google নিজের রিমাইন্ডার যোগ করে না, আর ওয়ার্কআউট অ্যাপে কখনো দুবার দেখায় না। আবার ছুঁলে Google ক্যালেন্ডার থেকে শুধু ওয়ার্কআউটগুলো সরে যায়।",
    faq_q_sport_workout_gcal: "আমার ওয়ার্কআউট কি Google ক্যালেন্ডারে দেখা যেতে পারে?",
    workout_gcal_btn: "Google ক্যালেন্ডার",
