    workout_gcal_not_connected: "আগে সেটিংসে Google ক্যালেন্ডার যুক্ত করুন",
    workout_gcal_off_toast: "ওয়ার্কআউটগুলো Google ক্যালেন্ডার থেকে সরানো হয়েছে",
    workout_gcal_on_toast: "আপনার ওয়ার্কআউট Google ক্যালেন্ডারে চলে গেছে",
    faq_a_sport_workout_reminder: "হ্যাঁ – ওয়ার্কআউটে রিমাইন্ডার: ১০ মিনিট, ৩০ মিনিট বা এক ঘণ্টা আগে, অথবা নিজের পছন্দের সময় (ওয়ার্কআউটের সময় থাকতে হবে)। এটি অন্য রিমাইন্ডারের মতোই বাজে, একবার আর এক জায়গায়: অ্যাপ খোলা থাকলে অ্যাপে, নইলে ফোনে। \"হয়ে গেছে\" ওয়ার্কআউটটি ইতিহাসে লগ করে, আর \"এখনও না\" ৫ মিনিট পরে আবার মনে করায়।",
    faq_q_sport_workout_reminder: "ওয়ার্কআউটের আগে কি রিমাইন্ডার পাওয়া যায়?",
    workout_reminder_30min: "৩০ মিনিট আগে",
    workout_reminder_label: "রিমাইন্ডার",
    workout_reminder_need_time: "রিমাইন্ডার পেতে সময় দিন",
    faq_a_sport_workout_share: "⋯ → শেয়ার করুন-এ সপ্তাহটি আপনার থিমের রঙে কাচের মতো একটি ছবি হয়ে যায়, সাথে অ্যাপের একটি হালকা লিংক (ফোনে সরাসরি শেয়ার মেনু খোলে, কম্পিউটারে ছবিটি সেভ হয়)। ⋯ → প্রিন্টের জন্য PDF পুরো সপ্তাহের একটি পরিষ্কার পাতা খোলে, প্রতিটি ওয়ার্কআউট ও এক্সারসাইজের পাশে টিক দেওয়ার ঘর থাকে – \"PDF হিসেবে সেভ করুন\" বেছে নিন বা প্রিন্ট করুন। প্ল্যানটি সেটিংসের ডেটা রিপোর্টে খেলাধুলার অংশেও থাকে।",
    faq_q_sport_workout_share: "সপ্তাহের ওয়ার্কআউট কীভাবে শেয়ার বা প্রিন্ট করব?",
    share_image_saved: "ছবি সেভ হয়েছে – এখন সংযুক্ত করতে পারেন",
    share_save_image: "ছবি সেভ করুন",
    workout_pdf_btn: "প্রিন্টের জন্য PDF",
    workout_share_btn: "শেয়ার করুন",
    faq_a_sport_workout_board: "⋯ → সাপ্তাহিক বোর্ড-এ প্রতিটি দিন একটি কলাম: ওয়ার্কআউট অন্য দিনে টেনে নিন (ফোনে আগে চেপে ধরে রাখুন)। ওয়ার্কআউটে \"আমার রুটিনেও\" সেটিকে তার সময় ও দিনে আপনার রুটিনে রাখে, আর পরিবর্তন দুই দিকেই মিলে থাকে; আমার রুটিনের কোনো আইটেম থেকে \"আমার ওয়ার্কআউটে যোগ করুন\" উল্টোটা করে। যেকোনো জায়গায় ✓ দুই জায়গাতেই গোনা হয়, আর আমার দিন-এ এটি একবারই দেখায় – পানির পাশের চিপে।",
    faq_q_sport_workout_board: "ওয়ার্কআউট অন্য দিনে কীভাবে সরাব, আর আমার রুটিনের সাথে কীভাবে জুড়ব?",
