    faq_a_sport_workout_plan: "ওয়ার্কআউট ট্র্যাকিং-এ, \"আমার ওয়ার্কআউট\"-এর নিচে: + ওয়ার্কআউট – ধরন, দিন, সময়, সময়কাল, তীব্রতা ও জায়গা (\"অন্যান্য\"-ও)। স্ট্রেংথ, ফাংশনাল ও সাঁতারের ওয়ার্কআউটে এক্সারসাইজের তালিকা রাখা যায়, আর \"বিশ্রাম\" বিশ্রামের দিন চিহ্নিত করে। তৈরি প্ল্যান দিয়েও শুরু করা যায়। আজকের ওয়ার্কআউট বড় করে দেখায়, নিচে পুরো সপ্তাহ; ✓ সেটিকে তীব্রতাসহ ওয়ার্কআউটের ইতিহাসে লগ করে। ⋯-এ সাপ্তাহিক লক্ষ্য ঠিক করা যায় (ওয়ার্কআউট বা মিনিট) – প্রতিটি ওয়ার্কআউট তার তারাটি বয়ামে ফেলে দেয়।",
    faq_a_sport_workout_today: "আমার দিন-এ, পানির পাশে একটি ছোট চিপ আজকের ওয়ার্কআউট দেখায় – ছুঁলে বিস্তারিত, ✓ আর ▶ খোলে। ▶ টাইমার চালু করে, যা হোম স্ক্রিনের চিপেও চলতে থাকে, আর \"শেষ\" আসল সময় দিয়ে ওয়ার্কআউট লগ করে। New Me-এ \"নড়াচড়ার দুই সপ্তাহ\" চ্যালেঞ্জ চললে, লগ করা ওয়ার্কআউট সেখানে নিজে থেকেই গোনা হয়।",
