    faq_a_new_me_magic_themes: "New Me-এর সঙ্গে আসা পাঁচটি ঝলমলে থিম: জাদুর বন, তারার ধুলো, গোলাপ পরী, জাদুর মেরুজ্যোতি আর সোনালি গোধূলি। New Me-এর ভেতরে (⚙️ সেটিংস > রং) বা সেটিংস > চেহারা ও ডিসপ্লে থেকে একটি বেছে নিন, আর ঝিকমিকে একটি তুলি স্ক্রিনটিকে সেই থিমে রাঙিয়ে দেয়। জাদুর থিম পুরো অ্যাপে আর প্রতিটি ট্যাপে ঝিকিমিকি ছড়ায়। যেকোনো সময় অন্য যেকোনো থিমে ফিরে যেতে পারেন।",
