    apptour_m_presets_text: "আপনার সেভ করা খাবার এক জায়গায়: খোঁজা, সাম্প্রতিক, দিনের সময় অনুযায়ী – আর ＋ একটি খাবার আজ যোগ করে।",
    apptour_night_text: "🌙 পুরো অ্যাপকে অন্ধকার করে, ☀️ দিন ফিরিয়ে আনে।",
    apptour_noteline_text: "লিখে ➤ ট্যাপ করুন – এটি আপনার নোটে সেভ হয়। শুরুর 📝 এটিকে 🛒 কেনাকাটা বা 🍎 সেভ করা খাবারে বদলায়।",
    apptour_search_text: "নোট, কেনাকাটা, ক্যালেন্ডার, রেসিপি, নোটবুক, লক্ষ্য, টেবিল আর বই – একবার খুঁজলেই সব পাওয়া যায়।",
    faq_a_new_me_ai_menu: "মেনুর আগে প্রশ্নাবলি জানতে চায় আপনি কোন কোন খাবার কখন খান (২ বেলা খাবার + একটি নাস্তা, ২ বেলা খাবার + হালকা রাতের খাবার, বা দুটোই), সন্ধ্যায় ছোট কিছু খান কি না আর কটায়, কী খান না, আর কফি বা চা কীভাবে খান। তারপর AI প্রতিটি খাবারের জন্য ৩টি বিকল্প তৈরি করে – প্রতিটি দিনের মধ্যে সেই খাবারের ভাগ অনুযায়ী, তাই দিনের মোট এখনও ঠিক ১,৩০০ বা ১,৫০০ থাকে – সঙ্গে পানীয়ের পরামর্শ, যা আপনার নির্দিষ্ট পানীয় হিসেবে সেভ হয়। প্রতিটি খাবারে ২টি পর্যন্ত পছন্দের বেছে নিন; মূল মেনুর বিকল্প ঠিক নিচে আছে, আর 🔄 বদলান-এ সেগুলো আপনার নিজস্ব মেনুর পরে আসে। 🔄 অন্য বিকল্প নতুন একটি সেট তৈরি করে (প্রতি প্রশ্নাবলিতে ৩ বার)। উত্তর বদলাতে বা যেকোনো সময় নতুন মেনু তৈরি করতে: ⚙️ সেটিংস → ✨ নিজস্ব মেনু (AI)।",
