    nm_sales_premium: "পুরো প্রিমিয়াম অন্তর্ভুক্ত",
    nm_unlock_premium: "আর পুরো প্রিমিয়ামও খুলে গেছে।",
    settings_sub_status_newme: "প্রিমিয়াম আপনার New Me-তে অন্তর্ভুক্ত।",
    room_back_to_shelf: "তাকে",
    faq_a_new_me_day_total: "প্রতিটি দিন ঠিক প্ল্যানে মেলে: খাবার, সারাদিনে কফি ও পানীয়ের জন্য প্রায় ১৫০ ক্যালরি, আর সন্ধ্যার জন্য যা বেছে নেওয়া হয়েছে – হালকা কিছু খাওয়া বা কিছু পান করা। সন্ধ্যার জন্য পছন্দের ৩টি পর্যন্ত বেছে নিন (যেমন একটি কলা, একটি দই বা ২ টুকরো ডার্ক চকলেট; অথবা হারবাল চা, অল্প দুধ দেওয়া চা বা গরম দুধ), আর সেগুলোর ক্যালরি খাবার থেকে কমে। প্রতিটি পছন্দ নিজে থেকেই সমান হয়: ছোট বা বড় বিকল্প, বাদ পড়া খাবার, ছোট সকালের নাস্তা ও তার সঙ্গে আসা ছোট খাবার, বা সন্ধ্যা – পার্থক্যটা খাবারগুলোতে যোগ হয় বা তা থেকে বাদ যায়, প্রতিটির আকার অনুযায়ী, আর প্রতিটি খাবারের নিচে লেখা থাকে কত (+ বা −) এবং কী যোগ বা বাদ দেওয়া যায়। আগে থেকে টিক দেওয়া খাবার যেমন লেখা হয়েছিল তেমনই থাকে। প্রশ্নাবলিতে প্রতিটি খাবারের পাশে তার সংশোধন দেখা যায়, আর একটা ছোট বাক্স খাবার, পানীয়, সন্ধ্যা আর মোট দেখায়। সেদিন অন্য কিছু খেতে ইচ্ছে করছে? মোট ক্যালরি একই রাখুন, বা কম।",
    faq_q_new_me_day_total: "New Me-র একটা দিন ঠিক ১,৩০০ / ১,৫০০-এ কীভাবে মেলে, আর পানীয় কোথায় গোনা হয়?",
