    books_quotes_chip: "উদ্ধৃতি",
    faq_a_book_quotes: "গোপন ঘরের তাকে (উদ্ধৃতি), বা পড়ার কোণে ছোট 💬 উদ্ধৃতি চিপে – দুটো একই তালিকা। \"+ উদ্ধৃতি\" ট্যাপ করুন, লাইনটা লিখুন আর পড়ার কোণ থেকে বই বেছে নিন, অথবা \"✏️ অন্যান্য\" দিয়ে অন্য নাম লিখুন; লেখক ঐচ্ছিক। ✏️ উদ্ধৃতি বদলায় আর 🗑️ মুছে দেয়। উদ্ধৃতিগুলো বুকমার্ক, সোয়াইপ করে দেখা যায় – ওপরের 🎨 দিয়ে ছবি বা কার্ডের দেয়ালে বদলানো যায়।",
    faq_a_room_wish_jar: "গোপন ঘরের তাকে স্বপ্নের জন্য একটা কাচের জার আছে। সবচেয়ে ওপরের তাকের ছোট জারে ট্যাপ করুন (বা তাক > ইচ্ছের জার) আর লিখুন আপনি জীবন কেমন চান – যত খুশি বড়, ঠিক-ভুল নেই। প্রতিটি ইচ্ছে একটা চিরকুটে ভাঁজ হয়ে জারে পড়ে। \"একটা চিরকুট তুলুন\" যেকোনো একটা খোলে, আর প্রতিটি চিরকুট আলাদা করেও খোলা যায়। একই ইচ্ছে দ্বিতীয়বার খোলার সময় থেকে সেটাকে লক্ষ্য বানিয়ে ছোট ছোট ধাপে ভাগ করা যায়। সপ্তাহে একবার আপনার কোনো এক ইচ্ছের চিরকুট আলতো করে ভেসে ওঠে – কোনো চাপ নেই, শুধু মনে করিয়ে দেওয়া আপনি কোন দিকে যাচ্ছেন।",
