    faq_a_saved_meals_page: "সংরক্ষিত খাবারের নিজস্ব একটি পাতা আছে: পুষ্টি এবং পরিমাপ > ⭐ সংরক্ষিত খাবার (বা মেনুতে ⭐)। ওপরের খোঁজ নাম বা উপকরণ দিয়ে খাবার খুঁজে দেয়, \"সম্প্রতি ব্যবহৃত\"-তে দেখা যায় সম্প্রতি কী যোগ করেছেন, আর ট্যাবগুলো (সকালের নাশতা, দুপুরের খাবার, রাতের খাবার, স্যুপ…) দিনের প্রতিটি সময় দেখায়। \"+ আজ\" খাবারটিকে আজকের দৈনিক খাবার ট্র্যাকারে পরের খালি জায়গায় যোগ করে। বদলাতে বা মুছতে কোনো খাবারে ট্যাপ করুন, আর ওপরের ＋ নতুন খাবার যোগ করে।",
