    faq_a_notes_sticky_look: "নোটগুলো কাচের কার্ডের একটি ছোট তালিকা – নোটের ওপরের 🎨 সব নোটের চেহারা বদলায়: তালিকা, ওপরের দিনের বোতামগুলো আর যে জানালায় নোট লেখা হয় – কাচ, পরিষ্কার তালিকা, ইনডেক্স কার্ড বা ওয়াশি টেপ। টেনে নেওয়ার সময় নোটটি ঠিক নিজের চেহারা আর রঙেই থাকে। খুলতে কোনো নোটের লেখায় ট্যাপ করুন – সেখানে নোটটি বদলাতে পারবেন, রং বদলাতে পারবেন এবং শেষবার কখন লেখা হয়েছিল দেখতে পারবেন। কাজ হয়ে গেলে ○ ট্যাপ করুন, আর × নোটটিকে আর্কাইভে সরিয়ে দেয় (তালিকার নিচের 🗑️ থেকে ফিরিয়ে আনা যায়)। ক্রম বদলাতে, “পরে”-র নিচে নিতে বা ওপরের কোনো দিনে রাখতে ⠿ ধরে টানুন। ! একটি নোটকে জরুরি হিসেবে চিহ্নিত করে – নোটটি আলতো করে ওপরের প্রথম সারিগুলোতে উঠে যায়, একটি ছোট “জরুরি” ট্যাগসহ; আবার ট্যাপ করলে চিহ্নটি সরে যায়।",
    faq_q_notes_sticky_look: "নোট কীভাবে খুলব, বদলাব বা সরাব?",
    note_to_archive_btn: "আর্কাইভে সরান",
    faq_a_routine_clash: "সেই সময়ে একই দিনগুলোতে আগে থেকে কিছু থাকলে দুটি বিকল্প আসে: \"বদলান\" – নতুনটি ওই সময় পায় আর আগেরটির জন্য অন্য সময় বেছে নেওয়া হয় (আগের কোনো জিনিস সম্পাদনার সময় তার আগের সময়টি প্রস্তাব করা হয়, ফলে দুটো শুধু জায়গা বদল করে), অথবা \"দুটোই\" – দুটোই একই সময়ে থাকে, একটির নিচে আরেকটি। দিন আলাদা হলে (যেমন একটি রবি–বৃহস্পতি আর অন্যটি শুক্রবার) কিছুই জিজ্ঞেস করা হয় না।",
    faq_q_routine_clash: "রুটিনে আগে থেকে ভরা সময়ে কিছু রাখলে কী হয়?",
