    routine_clash_title: "{time}-এ আগে থেকেই আছে: {title}",
    faq_a_new_me_coffee: "আজকের মেনুর নিচে একটি ছোট সারাংশ আছে: আজকের সব খাবার মিলে কত ক্যালরি, কফি আর পানীয়ের জন্য কতটা বাকি, আর বেছে নেওয়া কফি ও পানীয়ের বোতাম – এক ট্যাপেই সেটি পানীয়তে যোগ হয়। বোতামগুলোর নিচে \"পছন্দের ৩টি পর্যন্ত বেছে নিন\"-এ (আর প্রশ্নাবলিতেও) বেছে নিন কী দেখাবে: জল / সোডা ওয়াটার, হারবাল চা, ডায়েট পানীয়, ব্ল্যাক / আমেরিকানো (~5), অল্প দুধ দেওয়া চা (~25), ১০০ মি.লি. পর্যন্ত দুধ বা প্ল্যান্ট মিল্ক দিয়ে জলে বানানো কফি (~50), হালকা হট চকলেট, গরম দুধ বা সাধারণ কফি / লাতে (~120)।",
    faq_q_new_me_coffee: "কফি কোথায় যোগ করব, আর দিনের কতটা বাকি তা কীভাবে জানব?",
