    nm_late_room_line: "ঘুমের আগে হালকা কিছু · আজ ~{n} ক্যালরি বাকি",
    faq_a_recipe_examples: "আপনার নিজের রেসিপির নিচে উদাহরণ রেসিপি আছে: নাশতা, সালাদ, স্যুপ, প্রধান পদ, সাইড ডিশ, স্ন্যাক, মিষ্টান্ন আর ভিগান খাবার। প্রতিটিতে প্রস্তুতির সময়, প্রতি পরিবেশনে ক্যালোরি আর এক পরিবেশন কত গ্রাম তা লেখা আছে। খুলতে রেসিপিতে ট্যাপ করুন, আর \"আমার রেসিপিতে সেভ করুন\" আপনার নিজের একটি কপি বানায়, যা বদলানো যায়। বিভাগের ট্যাগগুলো ছাঁকে, আর একই ট্যাগে আবার ট্যাপ করলে সব দেখা যায়।",
    faq_a_recipe_grams: "রেসিপির ভেতরে, ক্যালোরির পাশে লেখা থাকে \"1 পরিবেশন ≈ X গ্রাম\"। নিজের রেসিপিতে রেসিপির ফর্মে \"প্রতি পরিবেশনে গ্রাম\" (আর চাইলে প্রস্তুতির সময়) লিখুন: দুটোই ঐচ্ছিক, আর সময় রেসিপির রঙিন ফিতায় দেখা যায়।",
