    recipes_examples_title: "উদাহরণ রেসিপি",
    faq_a_recipe_scan_multi: "হ্যাঁ। \"রেসিপি যোগ করুন\"-এ 📷 ট্যাপ করে একটি বা কয়েকটি ছবি বেছে নিন (6টি পর্যন্ত; PDF-ও চলবে)। প্রতিটি একটি ছোট তালিকায় দেখা যায়, সেখানে বেছে নিন তাতে কী আছে: সব, উপকরণ বা প্রণালী, আর \"➕ আরেকটি ছবি\" দিয়ে আরও যোগ করুন। তারপর \"✨ রেসিপি স্ক্যান করুন\" ট্যাপ করুন: AI সবকিছু ক্রম অনুযায়ী, পুনরাবৃত্তি ছাড়া একটি রেসিপিতে জুড়ে দেয়, আর এটি একটিই স্ক্যান হিসেবে গোনা হয়। AI সহকারীর 📷 ছবি থেকে বেছে নেওয়া কয়েকটি ছবিও এখানেই খোলে।",
