    faq_a_note_written_at: "নোট খুলতে তার লেখায় ট্যাপ করুন। ভেতরে, লেখার নিচে দেখা যায় শেষবার কখন লেখা হয়েছিল, ঠিক তারিখ ও সময়সহ। শুধু লেখাটি বদলালেই এটি আপডেট হয়: আর্কাইভ করে ফিরিয়ে আনা, ✓ দেওয়া, রং বা নোট সরানো এটি বদলায় না।",
    faq_q_note_written_at: "কোনো নোট কখন লেখা হয়েছিল তা কীভাবে দেখব?",
    note_written_at: "শেষবার লেখা হয়েছে: {date}",
    faq_a_new_me_month: "জাদুর ব্যাকপ্যাকে → মাসিক ক্যালেন্ডার: প্রতিটি দিন রঙিন হয় কতগুলো খাবারে টিক পড়েছে সেই অনুযায়ী, ‹ › তীর দিয়ে মাস বদলানো যায়, আর ক্যালেন্ডারের নিচে মাসের দৈনিক গড় ক্যালরি লেখা থাকে। কোনো দিনে ট্যাপ করলে দেখা যায় সেদিন কতগুলো খাবারে টিক পড়েছে আর কত ক্যালরি খাওয়া হয়েছে।",
