    faq_a_new_me_small_breakfast: "একটি হালকা সকালের নাস্তা (প্রায় ১৭০ ক্যালরি): স্প্রেড বা চিজসহ একটি স্পেল্ট পিটা (১০০ ক্যালরি পর্যন্ত), এবং একটি সবজি – পছন্দের ৩টি পর্যন্ত বেছে নিন, যেমন ১ চা-চামচ চকলেট স্প্রেড, ১ চা-চামচ পিনাট বাটার বা এক স্লাইস শক্ত চিজ (২২% পর্যন্ত)। এটি ছোট বলে এর সঙ্গে অন্য সময়ে “সঙ্গে একটি ছোট খাবার” আসে (দেড় ঘণ্টা পরে, যেমন 11:30 → 13:00 – অন্য যেকোনো সময়ও বেছে নেওয়া যায়): আরেকটি পিটা ও স্প্রেড, প্রোটিন দই ও ফল, রাইস কেক ও চিজ, সিরিয়াল ও দুধ বা আধখানা পিটা ও ডিম – প্রায় ২০০ ক্যালরি পর্যন্ত, নিজস্ব ✓ সহ। এরপরও যা থেকে যায় তা অন্য খাবারগুলোতে ভাগ হয়, আর প্রতিটি খাবার দেখায় তাতে কতটা যোগ হলো, তাই দিনের মোট পরিকল্পনামতোই থাকে। প্রশ্নাবলিতে বেছে নিন, অথবা 🔄 দিয়ে শুধু আজকের জন্য এতে বদলান – যেমন যখন সকালের নাস্তা দেরিতে হয়।",
