    faq_a_new_me_favorites: "হ্যাঁ। প্রশ্নাবলিতে (এবং সেটিংস থেকে আবার পূরণ করার সময়ও) প্রতিটি খাবারের জন্য ২টি পর্যন্ত বিকল্প বেছে নেওয়া যায়। প্রথমটি মেনুতে দেখা যায়, আর তার নিচে দ্বিতীয়টির জন্য একটি «বা» লাইন থাকে – সেখানে ট্যাপ করলে শুধু আজকের জন্য সেটিতে বদলে যায়। আর সকালের খাবার সময়মতো খাওয়া না হলে, «⏰ পরে» সেটিকে দিনের পরের সময়ে সরিয়ে দেয়, ক্যালরি না বদলে।",
    faq_a_theme_mode: "কিছু বিশেষ থিম ডার্কে সবচেয়ে সুন্দর দেখায় – জলরং, অরোরা, বার্বি আর দুটি ঝলমলে থিম – তাই এগুলোর একটি বেছে নিলে অ্যাপ ডার্ক মোডে চলে যায়, আর অন্য যেকোনো থিম (রকেটও) বেছে নিলে লাইটে। কালো ও গাঢ় ধূসর ডার্কই থাকে। পরে যেকোনো সময় মেনুর 🌙 বা সেটিংসের লাইট মোড দিয়ে বদলানো যায়।",
    faq_a_water_month: "পানি ট্র্যাকিংয়ে। আজকের রেকর্ডের প্রতিটি এন্ট্রির পাশে যোগ করার সময় দেখা যায়, আর \"মাসিক তালিকা\" পুরো মাস খুলে দেয়: প্রতিটি দিনে দেখা যায় কত লিটার খাওয়া হয়েছে (দৈনিক লক্ষ্য পূরণ হলে ✓), আর কোনো দিনে ট্যাপ করলে সেদিনের এন্ট্রিগুলো সময়সহ দেখা যায়।",
