    faq_a_room_records: "রেকর্ড প্লেয়ারটি শুরু থেকেই ঘরে আছে, আরামকেদারার পাশে কাটা গাছের গুঁড়ির ওপর। এর রেকর্ডগুলো YouTube-এ গত কয়েক বছরের বড় হিট গানের অফিশিয়াল ভিডিও খোলে, আর তার নিচে আছে পাঁচটি শান্ত সুর যা এখানেই ঘরে বাজে – বাজার সময় রেকর্ড ঘোরে, আর \"⏹ থামাও\" গান বন্ধ করে।",
    faq_a_room_roof_gifts: "এগুলো আসে ৮ম চাবির সঙ্গে। দূরবিনে ট্যাপ করলে তার ভেতর দিয়ে তাকানো যায়: রাতের আকাশ কাছ থেকে – চারপাশ দেখতে টেনে নিন (বা তীর ব্যবহার করুন) – আর আপনার শেষ হওয়া চ্যালেঞ্জগুলো তাতে একটি নক্ষত্রমণ্ডল আঁকে, প্রতিটি চ্যালেঞ্জের জন্য একটি তারা; কোনো তারায় ট্যাপ করলে দেখা যায় সেটি কোন চ্যালেঞ্জ ছিল। ছোট সিন্দুকে ট্যাপ করলে সেটি খোলে – আপাতত সেটি খালি – আর আবার ট্যাপ করলে বন্ধ হয়ে যায়।",
