    faq_a_new_me_home_btn: "New Me থাকলে হোম স্ক্রিনের ওপরে ফোকাস মোডের পাশে ছোট 💎 আজকের মেনু খোলে। আজকের খাবারগুলো 'আমার দিন'-এও দেখা যায়, প্রতিটির সঙ্গে ✓।",
