    faq_a_home_note_line: "হোম স্ক্রিনের মাঝের লাইনে লিখে ➤ (বা Enter) চাপুন – এটি নোটে সেভ হয়ে যায়। লাইনের শুরুতে 📝-এ ট্যাপ করলে এটি 🛒 হয়ে যায়: তখন যা লিখবেন তা কেনাকাটার তালিকায় যাবে। আরেকবার ট্যাপ করলে 🍎: কয়েকটা অক্ষর লিখুন, মিলে যাওয়া সেভ করা খাবার দেখা যাবে, আর একটায় ট্যাপ করলে তা আজকের খাবারে লেখা হবে। 🎤 দিয়ে শুধু বলেও লেখা যায়।",
