    faq_q_night_mode: "নাইট মোডে কীভাবে যাব?",
    menu_day_mode: "ডে মোড",
    menu_night_mode: "নাইট মোড",
    faq_a_secret_room_yoga: "বনের পথের শেষে একটা জ্বলজ্বলে ফটক আছে, আর তার পেছনে, একটা জলপ্রপাতের পাশে, বনের প্রাণীরা – লুমি, পাফি, নিক্সি আর স্পার্কলেট – অর্ধবৃত্তে নিজেদের ম্যাটের ওপর বসে আছে, আর যোগ শিক্ষিকা ফ্লোরা তাদের মুখোমুখি পাথরের ওপর রাখা একলা ম্যাটটিতে বসে আছেন। ফ্লোরার ওপর ট্যাপ করুন: তিনি চোখ খোলেন, সবকিছু কাছে চলে আসে, আর আলাপ শুরু হয় ধীরে, পড়ার সময় দিয়ে – ফ্লোরা জিজ্ঞেস করেন সবাই কেমন আছে, প্রতিটি প্রাণী নিজের মুখে উত্তর দেয় (প্রতিটি লাইনের পাশে যে কথা বলছে তার একটা ছোট ছবি থাকে), তারপর তিনি আপনাকে জিজ্ঞেস করেন কাছের মানুষদের সঙ্গে কেমন লাগছে। আলাপ এগোয় আপনার উত্তর অনুযায়ী – ভালো মানুষ, কঠিন কেউ, বা একটু একাকিত্ব। প্রতিটি পথ শেষ হয় একটা ছোট মিশন (যা সরাসরি আমার দিন-এ যোগ করা যায়; মিশনটি যদি কিছু লেখার হয়, তাহলে লেখার জায়গা থাকে, আর লেখাটি জাদুর ডায়েরিতে সংরক্ষিত হয়) আর একসঙ্গে তিনটি শ্বাসের একটা আসন দিয়ে। ↩ এক ধাপ পিছিয়ে যায় আর ✦ নতুন আলাপ শুরু করে। পরের চাবি জলপ্রপাত খোলে: পাথরে বসলেই সব মিলিয়ে যায়, থাকে শুধু জলের শব্দ। পুকুরের ওপর ঝুঁকলে জল থেকে একটি প্রশ্ন ভেসে ওঠে – আসল আপনি আজ কী করতেন? – আর উত্তরটি 'আমার দিন'-এ একটি ছোট কাজ হয়ে যায়। এটা একটা মিষ্টি মুহূর্ত, কোনো বিশেষজ্ঞের সঙ্গে কথা বলার বিকল্প নয়।",
