    routine_time_taken: "এই সময়ে আগে থেকেই কিছু আছে: {title}",
    faq_a_new_me_times: "শুরুর প্রশ্নাবলিতে, আর যেকোনো সময় New Me সেটিংস → \"খাবারের সময়\"-এ। রুটিনে আগে থেকেই খাবারের সময় থাকলে সেখান থেকে নেওয়া হয় – আর রুটিনের খাবারগুলো লুকিয়ে তাদের জায়গায় New Me-এর খাবার দেখানো যায়। না থাকলে বেছে নিন দিনে কয়বার খাবার (২ বেলা খাবার + একটি নাস্তা / ২ বেলা খাবার + হালকা রাতের খাবার / ২ বেলা খাবার + একটি নাস্তা + হালকা রাতের খাবার) আর প্রতিটি কখন। \"২ বেলা খাবার + একটি নাস্তা\"-এ সেগুলো হলো 11:30-এ দুপুরের খাবার, 16:00-এ নাস্তা আর 19:00-এ রাতের খাবার (যেকোনোটি বদলানো যায়)। এগুলোই সব জায়গায় খাবারের সময়: করিডোরে, \"আমার দিন\"-এ, \"আমার রুটিন\"-এ আর রিমাইন্ডারে। যা-ই বাছাই করা হোক, দিনের ক্যালরি একই থাকে: যা বাদ যায় তা বাকি খাবারগুলোতে ভাগ হয়ে যায়।",
