    faq_a_routine_exact_time: "হ্যাঁ। নির্দিষ্ট সময়সহ AI-কে রুটিন বললে (যেমন \"16:10 ট্রেডিং\"), সময়টা ঠিক সেভাবেই সেভ হয় – পূর্ণ ঘণ্টায় গোল করা হয় না। রুটিনে যা লেখা আছে তা সবসময় বোর্ডে দেখা যায়, ঘণ্টার সেটিংসে সেই ঘণ্টা বাছাই করা না থাকলেও; আর যে ঘণ্টায় কিছু লেখা আছে তা সরাতে গেলে আগে জিজ্ঞেস করা হয়। সময় হাতেও বদলানো যায়: আইটেমের উইন্ডোতে সময়ে ছুঁয়ে ঘণ্টা আর মিনিট বেছে নাও।",
