    routine_daysoff_which: "কোন কোন দিন?",
    faq_a_secret_room_diary: "শুধু আপনি। ডায়েরির পাতাগুলো আপনার অ্যাকাউন্টে সেভ হয়, তাই সব ডিভাইসে থাকে, আর অন্য কেউ দেখতে পায় না। গোপন ঘরে ডেস্কের ওপরের জাদুর ডায়েরিটি এটি খোলে, আর গানের কোণের ডায়েরিটিও। নতুন পাতার নিচে একটা ভাঁজ করা মাসিক ছক আছে: যেদিন পাতা আছে সেদিনে একটা বিন্দু থাকে, আর কোনো দিন ছুঁলে সেদিনের পাতাগুলো খোলে – সেখানে পাতা মুছেও ফেলা যায়। ডায়েরি খুলে গেলে সেটিকে মূল মেনুতেও যোগ করা যায় – ডায়েরির ভেতরের বা New Me-এর সেটিংসের সুইচ দিয়ে।",
    faq_a_secret_room_places: "বনের ফটকের প্রতিটি প্রবেশপথ নিজের চাবিতে খোলে। পেছনে আছে: সমুদ্রমুখী বারান্দা (ছোট টেবিলে আলাদিনের প্রদীপ – ছুঁলেই তার ভেতর থেকে জাদুকরী কুয়াশায় বনের এক আত্মা উঠে আসে, চারপাশে ঘুরে ঘুরে আপনার ইচ্ছে নিয়ে কথোপকথন শুরু করে – দেখুন “প্রদীপের জিন কী করে?”), গিটার আর ডায়েরি (গিটার একটা ছোট, শান্ত সুর বাজায় আর নিজে থেকেই থেমে যায়, আর গাছে ঝোলানো তিনটি রেকর্ডের প্রত্যেকটি নিজের জাদুকরী সুর বাজায় – আবার ছুঁলে থেমে যায় – আর কাটা গুঁড়ির ওপরের ডায়েরিতে লেখা যায়), শ্বাস নেওয়ার ঘর (সূর্যাস্তের এক শান্ত হ্রদ – জলে একটি পদ্মের লণ্ঠন ভাসছে: সেটা ছুঁয়ে একটা ইচ্ছে লিখুন, আর ইচ্ছেটা নিয়ে সেটা ভেসে চলে যায় হ্রদের অনেক দূরে, গভীরে; জাদুর কাঠি দিয়ে বালিতে লেখা যায় যা ছেড়ে দিতে ইচ্ছে করে, আর তা থেকে যায় যতক্ষণ না আঙুল দিয়ে মুছে ফেলা হয়) আর বনের পথ (এটি রাতে খোলে, আর লণ্ঠন ছুঁলে দিন হয়ে যায়; বেঞ্চে বসা যায়, আর ফলক ছুঁলে সেটা কাছে আসে – ছয়টা ছোট প্রশ্নসহ একটা বোর্ড, যাতে টিক দেওয়া যায়)। তালাবন্ধ প্রবেশপথে দেখা যায় আর কয়টা চাবি বাকি। পথের শেষে একটা জ্বলজ্বলে ফটক জলপ্রপাতের পাশের যোগব্যায়ামে নিয়ে যায় – আর সেখান থেকে জলপ্রপাতে।",
