    dev_weather_preview_label: "প্রিভিউ – শুধু আপনার অ্যাকাউন্টে:",
    faq_a_ai_chat: "বাবলে ট্যাপ করুন, একটি চ্যাট খুলে যাবে। কী করবেন বেছে নিন – ক্যালেন্ডারের জন্য কিছু, কী খেয়েছেন, রেসিপির ছবি বা নতুন টেবিল – অথবা শুধু লিখে দিন, সহকারী নিজেই বুঝে নেবে। চাইলে 🎙️-এ ট্যাপ করে টাইপ না করে কথাও বলতে পারেন। ক্যালেন্ডারের জন্য একবার, প্রতি সপ্তাহে বা প্রতিদিন বেছে নেওয়া যায়। উত্তর চ্যাটেই আসে, আর সেখান থেকে অন্য কিছুতে যাওয়া যায় বা ক্যালেন্ডার / যা খেয়েছেন তা খোলা যায়।",
    faq_a_new_me_hall: "New Me খোলে এক জাদুর বনের ফটকে, আর এর প্রতিটি প্রবেশপথ একটি জায়গা: বিশাল গাছের গোল দরজা নিয়ে যায় গোপন ঘরে, ফাঁপা গুঁড়ি – সমুদ্রমুখী বারান্দায়, মাশরুমের বাড়ি – গিটার আর ডায়েরিতে, উইলোর ছোট খিলান – শ্বাস নেওয়ার ঘরে, উইলোর বড় খিলান – বনের পথে, আর মই-সহ ফুলের খিলানটি ছাদ খুললে উঠে যায় তারার ছাদে। তালাবন্ধ প্রবেশপথে একটি তালা দেখা যায়। পথে ভেসে থাকে আপনার চরিত্র, Sky, আর চারপাশে খেলার বোতাম: পরের মিশন, সপ্তাহের চ্যালেঞ্জ, পুরো New Me-সহ জাদুর ব্যাকপ্যাক, জগতের মানচিত্র আর টুলগুলো। ওপরের চাবিগুলোতে ট্যাপ করলে বোঝানো হয় কীভাবে চাবি পাওয়া যায়।",
    faq_a_new_me_routine_meals: "New Me-তে খাবার ঠিক করা থাকলে আর আমার রুটিনেও খাবার থাকলে, New Me জিজ্ঞেস করে সেগুলো লুকিয়ে তাদের জায়গায় New Me-এর খাবার দেখাবে কি না – যাতে কিছুই দুবার না দেখায়। তখন আমার রুটিন New Me-এর খাবারগুলো তাদের সময়ে দেখায়, 💎 আর ✓ সহ; খাবারের নামে ট্যাপ করলে অন্য খাবার বেছে নেওয়ার বা তার সময় বদলানোর একটি উইন্ডো খোলে, রুটিনের ওপরেই। কিছুই মুছে যায় না: সেগুলো New Me-র ⚙️ সেটিংস → রুটিনের খাবার থেকে ফিরে আসে, অথবা আমার রুটিনের ⚙️-এ “New Me-এর সঙ্গে সিঙ্ক” বন্ধ করলে। সক্রিয় New Me না থাকলে সেগুলো নিজে থেকেই ফিরে আসে।",
    faq_a_room_computer: "এটি একটি ছোট চ্যাট, যা শুরু হয় “আজকের দিনটা এ পর্যন্ত কেমন যাচ্ছে?” দিয়ে – ভালো, ব্যস্ত নাকি কঠিন – তারপর ধাপে ধাপে আপনার সঙ্গে এগোয়, শেষে একটি ছোট মিশন পর্যন্ত (যা সরাসরি আমার দিন-এও যোগ করা যায়)। উত্তরে ট্যাপ করা যায় বা খোলাখুলি লেখা যায় – যা লেখা হয় তা সবচেয়ে কাছের উত্তরের সঙ্গে মিলে যায়। “↩ পেছনে” এক ধাপ পিছিয়ে যায়, যাতে অন্যভাবে উত্তর দেওয়া যায়, আর “নতুন চ্যাট” যেকোনো মুহূর্তে আবার শুরু করে। ব্যস্ত বা কঠিন দিনের পরে একই দিনে পরে আবার কম্পিউটারে ফেরা যায়: “আবার এসেছি...” কথোপকথন চালিয়ে যায়। নিচের সবুজ বাতি কম্পিউটার বন্ধ ও চালু করে। শুধু বেছে নেওয়া উত্তরগুলো সংরক্ষিত হয়, শুধু এই ডিভাইসে আর শুধু দিনের শেষ পর্যন্ত।",
