    pcx_a1a_q: "ফোন মনোযোগের এক নম্বর শত্রু, তাই এটা বিভ্রান্তির বিরুদ্ধে বিশাল জয়! স্ক্রল না করেই ঘণ্টার পর ঘণ্টা কেটে গেছে বুঝতে পেরে কেমন লাগল?",
