    pcx_a1a_t: "আগামীকালের ক্যালেন্ডারে 45 মিনিটের একটি নির্দিষ্ট ফোকাস সেশন রাখুন – ঘরে ফোন ছাড়া।",
    pcx_a1a_tn: "মনোযোগ নোঙর করুন",
