    pcx_a1b_t: "পরের কঠিন কাজের প্রথম, সবচেয়ে ছোট ধাপটি (সর্বোচ্চ 3 মিনিট) লিখে রাখুন।",
    pcx_a1b_tn: "পরের বাধা ভেঙে ফেলুন",
    pcx_a1c_q: "ইতিবাচক চাপ কখনো কখনো জাদু করে, আমাদের সেরাটা বের করে আনে। ডেডলাইন পেরিয়ে যাওয়ার পর এখন মাথাটা কেমন লাগছে?",
    pcx_a1c_r1: "বিশাল তৃপ্তি",
    pcx_a1c_r2: "কাজ হয়েছে, কিন্তু সব শক্তি শুষে নিয়েছে",
    pcx_a1c_s1: "সময়মতো কিছু শেষ করার রোমাঞ্চের তুলনা হয় না!",
