    pcx_a2_o1: "ভালো ঘুম / আজ সকালে নিজের যত্ন নিয়েছি",
    pcx_a2_o2: "আজ সকালে কিছু একটা মন ভালো করে দিয়েছে",
    pcx_a2_q: "কী সুন্দর! কিছু দিন আমরা ঘুম থেকে উঠি আর সব কিছু সহজে চলতে থাকে। আপনার কী মনে হয়, আজকের ভালো শক্তি কোথা থেকে আসছে?",
    pcx_a2a_q: "শরীরের মৌলিক চাহিদার বিকল্প নেই! শরীর যা দরকার তা পেলে মন 10 গুণ ভালো কাজ করে। সকালের রুটিনের কোন অংশটি সবচেয়ে বড় পার্থক্য গড়েছে?",
