    faq_a_dictation: "হ্যাঁ – দ্রুত নোট বা খাতার লেখার পাতার কোণে 🎤 মাইক্রোফোনে ট্যাপ করে বলুন: বলতে বলতেই অ্যাপের ভাষায় শব্দগুলো লেখা হয়ে যায়। থামাতে আবার ট্যাপ করুন। প্রথমবার ব্রাউজার মাইক্রোফোন ব্যবহারের অনুমতি চায়। Chrome / Android আর iPhone-এর Safari-তে কাজ করে। কম্পিউটারে মাইক্রোফোন আর Chrome, Edge বা Safari-র মতো ব্রাউজার দরকার – কিছু না থাকলে বার্তাটি ঠিক কী নেই তা বলে দেয়।",
    faq_q_dictation: "টাইপ না করে কি বলা যায়?",
    faq_a_secret_room: "New Me-এর ভেতরে একটি ঘর যা শুধু আপনার – বিশাল এক গাছের ভেতরে একটি বাড়ি। একবারে একটি দেয়াল দেখা যায়, আর তীর (বা সোয়াইপ) দিয়ে ঘোরা যায়। প্রথম চাবি আসে 3টি আলাদা দিনে কোনো খাবারে ✓ দেওয়ার পর, আর তা দরজা খোলে – সঙ্গে পুরো ঘরও: কম্পিউটার, খেলা, রেকর্ড প্লেয়ার, ভেতরে লাইব্রেরিসহ তাক আর বিড়াল। এরপর প্রতিটি শেষ হওয়া চ্যালেঞ্জ (সপ্তাহের চ্যালেঞ্জও) একটি চাবি দেয় যা পরের জায়গা খোলে: তারার ছাদ, সমুদ্রমুখী বারান্দা, গিটার আর ডায়েরি, শ্বাস নেওয়ার ঘর, যোগব্যায়ামসহ বনের পথ, জলপ্রপাত আর ছাদে একটি চমক – আর 8ম চ্যালেঞ্জ সমুদ্র থেকে একটি বোতল আনে, যার ভেতরে অতীতের চিঠি। কিছু খুললে একটি তীর সেখানে যাওয়ার পথ দেখায়। খেলার মেশিনের নিচের ছোট দরজাটিও খোলে – আপাতত এর পেছনের আলমারিটি ফাঁকা। তারার ছাদে ট্যাপ করা তারা উল্কার মতো খসে পড়ে, আর বিড়ালটি কুশনে বসে থাকে।",
