    faq_a_reminders_one_place: "প্রতিটি রিমাইন্ডার একবার, এক জায়গায় আসে। অ্যাপটি আপনার সামনে খোলা থাকলে (কম্পিউটার, iPad বা ফোনে) সেটি সেখানেই দেখা যায়; না হলে শুধু ফোনে বিজ্ঞপ্তি হিসেবে আসে। যেকোনো জায়গায় '✅ হয়ে গেছে, ধন্যবাদ!' বা 'বুঝেছি!' চাপলে সেটি সব ডিভাইসে বন্ধ হয়ে যায় এবং আর ফিরে আসে না। 'এখনও না' সেটিকে পিছিয়ে দেয়: প্রতি 5 মিনিটে আবার আসে, প্রতিবার এক জায়গায়। তালিকায় কাজে ✓ দেওয়াও 'হয়ে গেছে' হিসেবে গণ্য হয়। কম্পিউটার ও ট্যাবলেটেও বিজ্ঞপ্তি পেতে সেটিংস > বিজ্ঞপ্তি-তে 'কম্পিউটার ও ট্যাবলেটেও' চালু করুন।",
    faq_q_reminders_one_place: "রিমাইন্ডার কেন শুধু একবার, আর শুধু ফোনেই আসে?",
    reminder_all_devices_hint: "সাধারণভাবে প্রতিটি রিমাইন্ডার একবার, এক জায়গায় আসে: ফোনে, বা সেই ডিভাইসে যেখানে অ্যাপটি আপনার সামনে খোলা আছে। এক জায়গায় 'হয়ে গেছে' বা 'বুঝেছি' চাপলে সেটি সব জায়গায় বন্ধ হয়ে যায়।",
    reminder_all_devices_label: "কম্পিউটার ও ট্যাবলেটেও",
    myday_water_info: "পানির 8টি মাঝারি / ছোট গ্লাস গড়ে প্রায় 2 লিটার",
    faq_a_good_things: "সন্ধ্যায় (18:00 থেকে) তারিখের নিচে একটি ছোট বোতাম দেখা যায়: আজ ঘটা সর্বোচ্চ 3টি ভালো জিনিস লিখুন – একটাই যথেষ্ট। সেগুলো সংরক্ষিত হয়, আর 'আগের দিনগুলো'-তে আগে লেখা দেখা যায়। 'আজ রাতে না' এটিকে আগামীকাল পর্যন্ত লুকিয়ে রাখে, আর সেটিংস > ব্যক্তিগতকরণ ও ক্যালেন্ডার-এ পুরোপুরি বন্ধও করা যায়।",
    faq_a_home_countdown: "ক্যালেন্ডারে কোনো ইভেন্টে ⭐ দিন (ইভেন্ট তালিকায় পাশের তারা)। আগামী 100 দিনের মধ্যে সবচেয়ে কাছের তারা-দেওয়া ইভেন্ট তারিখের নিচে দেখা যায় – 'আর 3 দিন · মায়ের জন্মদিন', 'আগামীকাল · …' বা 'আজ · …'। ট্যাপ করলে ক্যালেন্ডারে সেই দিনে চলে যাবেন।",
    faq_a_home_streak: "এটি গোনে টানা কত দিন অন্তত একটি ✓ ছিল – আমার দিন, আমার রুটিন, আমার লক্ষ্যসমূহ বা New Me-এর যেকোনো কিছু। 2 দিন থেকে দেখা যায়। আজ এখনো ✓ না থাকলে ধারা ভাঙেনি – এখনো পুরো দিন বাকি। আর ধারা শেষ হলে এটি শুধু চুপচাপ মিলিয়ে যায়, কোনো অপরাধবোধ ছাড়াই।",
    faq_a_home_weather: "সেটিংস > ব্যক্তিগতকরণ ও ক্যালেন্ডার-এ 'হোম স্ক্রিনের আকাশে আবহাওয়া' চালু করুন এবং অবস্থানের অনুমতি দিন। তখন হোম স্ক্রিনের আকাশে আপনার জায়গার আসল আবহাওয়া দেখা যায় – সূর্য (রাতে চাঁদ আর তারা), মেঘ, বৃষ্টি, তুষার, ঝড় বা কুয়াশা – সব থিমে, প্রায় প্রতি 40 মিনিটে আপডেট হয়। আনুমানিক অবস্থান (প্রায় 1 কিমি পর্যন্ত গোল করা) শুধু আপনার ডিভাইসে থাকে এবং আমাদের সার্ভারের মাধ্যমে MET Norway থেকে দেখা হয়। ডিফল্টভাবে এটি বন্ধ। সুইচের নিচে লেখা থাকে এখন বাইরে আবহাওয়া কেমন – যেমন ⛅ আংশিক মেঘলা, তাই আকাশে সূর্য আর মেঘ দুটোই দেখা যায়।",
