    faq_a_home_focus: "হোম স্ক্রিনের উপরে ◎ ট্যাপ করুন: এখনকার একটি জিনিস – এই ঘণ্টায় যা আছে, বা আজকের তালিকার পরের জিনিস – একটি বড় ✓ আর দ্রুত নোট ছাড়া সব লুকিয়ে যায়। ✓ দেওয়ার পর পরের জিনিসটি আসে। উপরে 'ফোকাস মোড ✕' ট্যাপ করলে সব ফিরে আসে।",
    faq_a_home_search: "মেনু ☰ খুলুন – সার্চ একদম ওপরে। অন্তত 2টি অক্ষর লিখুন: ফলাফল আসে আপনার নোট, কেনাকাটার তালিকা, ক্যালেন্ডার, রেসিপি, নোটবুক (শিরোনাম ও পাতার লেখা), লক্ষ্য, টেবিল আর বই থেকে, ধরন অনুযায়ী সাজানো – একটিতে ট্যাপ করে সরাসরি সেখানে যান।",
    faq_a_my_day: "'আমার দিন' আগের 'আজকের এক ঝলক' আর 'আমার রুটিন'-কে একটি টাইমলাইনে একসঙ্গে আনে। হোম স্ক্রিনের নিচে দেখা যায় কতটা হয়েছে, এখন বা পরে কী আছে (দ্রুত ✓ সহ), আর শিরোনামের পাশে +1 দিয়ে এক গ্লাস পানি। ট্যাপ করুন (বা উপরে সোয়াইপ করুন) পুরো দিন খুলতে: উপরে সময় ছাড়া জিনিসগুলো, তারপর ঘণ্টা ধরে সবকিছু – ক্যালেন্ডারের কাজ, ইভেন্ট ও মিটিং, সাপ্তাহিক নির্দিষ্ট সময়, আজকের রুটিন, লক্ষ্যের ছোট ছোট পদক্ষেপ আর New Me-এর খাবার – সঙ্গে 'এখন'-এর একটি রেখা। কাজ, রুটিন বা মিটিং ও ইভেন্ট দিয়ে ফিল্টার করুন। এখানের ✓ অন্য সব জায়গার (আমার রুটিন, আমার লক্ষ্যসমূহ, ক্যালেন্ডার) একই ✓, আর কোণে একটি ডেইজি ফোটায়। 'রুটিন সম্পাদনা' 'আমার রুটিন' খোলে (মেনুতেও আছে), আর '＋ আজকের জন্য যোগ করুন' আজকের জন্য একটি কাজ যোগ করে। \"আমার দিন\" শিরোনামে (বা ওপরের ছোট দাগে) ট্যাপ করলে এটি আবার বন্ধ হয়।",
