    faq_a_table_shopping_link: "কেনাকাটার তালিকার সঙ্গে যুক্ত ✓ কলামে (যেমন 'এই সপ্তাহের খাবার'-এর 'উপকরণ আছে'), যে সারিতে এখনো টিক নেই তার পাশে একটি 🛒 থাকে। এক ট্যাপে সেটি কেনাকাটার তালিকায় যোগ হয় – শুধু একবার, দুবার কখনো নয়। এখানে ✓ দিলে সেটি তালিকা থেকে সরে যায়; তালিকা থেকে মুছে দিলে এখানে আর 'তালিকায় আছে' দেখায় না; আর তালিকায় কেনা হয়েছে চিহ্ন দিলে এখানকার সারিটি নিজে থেকেই ✓ পায়। যেকোনো ✓ কলাম কলামের সেটিংসে যুক্ত বা বিচ্ছিন্ন করা যায়।",
