    faq_a_table_views: "টেবিলের ভেতরে ওপরে তিনটি ভিউয়ের মধ্যে বদলানো যায়: টেবিল (পাশে স্ক্রল করলেও প্রথম কলাম জায়গায় থাকে, আর নিচের সারি সংখ্যা যোগ করে ও ✓ গোনে), কার্ড (প্রতিটি সারি একটি কার্ড) আর বোর্ড (কার্ডগুলো একটি নির্বাচন কলাম, যেমন স্ট্যাটাস, অনুযায়ী সাজানো – কার্ড অন্য কলামে টেনে নিলে মান বদলায়)। কলামের শিরোনামে বা ↕ সাজান-এ ট্যাপ করলে সাজানো হয়, আর ফিল্টার শুধু কিছু সারি দেখায়; টেবিল দুটোই মনে রাখে। যেকোনো সারিতে ট্যাপ করলে সেটি পুরো কার্ড হিসেবে সম্পাদনার জন্য খোলে, আর ＋ কলাম সঙ্গে সঙ্গে একটি কলাম যোগ করে। ⋯-এ আছে কলামের তালিকা, নাম, আইকন আর পকেট, এবং টেবিল মোছা।",
