    faq_a_new_me_letter_gift: "New Me-এর শুরুতে (বা পরে, চ্যালেঞ্জে) ভবিষ্যতের নিজেকে একটি চিঠি লেখা যায়। সিল করার পর খোলার আগ পর্যন্ত তা পড়া বা বদলানো যায় না: তা খোলে গোপন ঘরে সমুদ্র থেকে আসা বোতলে, অথবা সব 20টি চ্যালেঞ্জ শেষ হলে – যেখানে একটি উপহারও অপেক্ষা করছে।",
