    faq_a_new_me_challenges: "🏆 চ্যালেঞ্জ-এ ২০টি চ্যালেঞ্জ আছে: ১০টি বড় (যেমন চিনি ছাড়া ৫ দিন, কার্বস ছাড়া এক সপ্তাহ, বা এক মাসে ৪ কেজি কমানো – প্রতিদিন ক্যালরি ঘাটতি, ওয়ার্কআউট আর চিনি নয়) আর ১০টি মিনি – এক সপ্তাহের ছোট অভ্যাস, যেমন চিনি ছাড়া দারুচিনি কফি। চ্যালেঞ্জ বাছাই করলে জিজ্ঞেস করা হয় কবে শুরু: আজ, আগামীকাল, আগামী সপ্তাহে বা অন্য তারিখে। একটি বড় আর একটি মিনি চ্যালেঞ্জ একসাথে চলতে পারে। চলমান চ্যালেঞ্জ মেনুর সবার ওপরে আর আমার দিনে দেখা যায়, দিনের জন্য ✓ সহ। চ্যালেঞ্জের প্রতি সপ্তাহে একটি ছুটির দিন (🍕) থাকে যা চ্যালেঞ্জ ভাঙে না, আর যে দিন চিহ্ন দেওয়া হয়নি সেটি ছুটির দিন হিসেবে গোনা হয় – আজ আর গতকাল দুটোই চিহ্নিত করা যায়। কিছু দিন নিজে থেকেই চিহ্নিত হয়: ওয়ার্কআউট ট্র্যাকিং-এ ২০ মিনিটের ওয়ার্কআউট, বা ✓ দেওয়া মেনুর খাবার। প্রতিটি চ্যালেঞ্জে একটি ⓘ আছে – ঠিক কী কী গণনা হয় (যেমন কার্বোহাইড্রেটের পুরো তালিকা) – চ্যালেঞ্জের ভেতরে এবং আমার দিনে তার পাশেও। এগুলোর নিচে, 🌱 ব্যক্তিগত বিকাশ-এ এক সপ্তাহের ৪৮টি ছোট চ্যালেঞ্জ আছে (এগুলো ২০টির মধ্যে গোনা হয় না) – দেখুন “সপ্তাহের চ্যালেঞ্জ কী?”।",
