    nm_tile_challenges: "চ্যালেঞ্জ",
    faq_a_workout_calories: "হ্যাঁ। প্রতিটি ব্যায়ামের জন্য পোড়ানো ক্যালোরির অনুমান করা হয় – ধরন, সময় আর আপনার সাম্প্রতিক ওজন থেকে (দৌড় আর সাইক্লিংয়ে দূরত্ব দিলে গতি থেকেও)। এটি ব্যায়ামের তালিকা আর মাসিক সারাংশে (পোড়ানো) দেখা যায়, আর সেই দিনের ক্যালোরি বাজেটে যোগ হয়: দৈনিক খাবার ট্র্যাকার, ক্যালোরি ও ওজন পরিমাপ আর New Me-র রিংয়ে। এটি অনুমান, তাই ~ দিয়ে দেখানো হয়।",
    faq_q_workout_calories: "ব্যায়াম কি দিনের ক্যালোরিতে গোনা হয়?",
    faq_a_new_me_flexible_menu: "হ্যাঁ। প্রশ্নাবলি ও সেটিংসে বেছে নিন দিনে কয় বেলা খাবেন – ২ বেলা খাবার + একটি নাস্তা / ২ বেলা খাবার + হালকা রাতের খাবার / ২ বেলা খাবার + একটি নাস্তা + হালকা রাতের খাবার – আর খাবারের কার্ডে ➖ সেটি বাদ দেয় (অন্তত ৩টি থাকে); '➕ আবার যোগ করুন' সেটি ফিরিয়ে আনে। যেভাবেই হোক দিনের ক্যালোরি একই থাকে: যা বাদ যায় তা বাকি খাবারগুলোতে ভাগ হয়, আর প্রতিটি খাবারের নিচে লেখা থাকে কতটা যোগ হলো আর কী খাওয়া যায়। খাবারে ✏️ সম্পাদনা চাপলে তার লেখা খোলে – ইচ্ছেমতো বদলান (যেমন রুটি ছাড়া বা আরেকটা ডিম) আর AI আবার ক্যালোরি ও প্রোটিন হিসাব করে। 🔄 বদলান-এ মেনুর বিকল্প, ⭐ সংরক্ষিত আর ✨ লিখে পাওয়া যায়; প্রতিটি পরিবর্তন শুধু আজকের জন্য বা এখন থেকে স্থায়ী হতে পারে। আর 'সারা দিন'-এর শেষে আছে ➕ খাবার যোগ করুন – মেনুর বাইরে যা খাওয়া হলো তা লিখুন, AI হিসাব করে আজকের সঙ্গে যোগ করে দেবে (✕ মুছে দেয়)।",
    faq_q_new_me_flexible_menu: "New Me-তে কি খাবারের সংখ্যা বদলানো যায়, বা নিজের খাবার খাওয়া যায়?",
