    faq_a_goal_days_challenge: "আমার লক্ষ্যসমূহ-এ ＋ ট্যাপ করুন (বা তৈরি উদাহরণ '🔥 8 দিন'), '📆 দিনের চ্যালেঞ্জ' বেছে নিন, কত দিন তা লিখুন এবং প্রতিদিন কী করবেন তা যোগ করুন (যেমন '30 মিনিট হাঁটা', 'আমার মেনু অনুযায়ী খাওয়া')। প্রতিদিন চ্যালেঞ্জের পথের নিচে সেই দিনের কাজগুলোতে টিক দিন – সবগুলোতে টিক পড়লে দিনটি গণনা হয়, পথ এক পাথর এগিয়ে যায় এবং আপনার 🔥 ধারাবাহিকতা বাড়ে (দৈনিক কাজ না থাকলে একটিমাত্র '✓ আজ করেছি' বোতাম থাকে)। কোনো কাজের পাশের 🔁 বোতাম সেটিকে আপনার বেছে নেওয়া ঘণ্টায় আমার রুটিন-এ যোগ করে: সেখানে টিক দিলে লক্ষ্যেও টিক হয়, আর উল্টোটাও। সাধারণ লক্ষ্যের মাইলফলকগুলোও একইভাবে আমার রুটিন-এ যোগ করা যায়।",
