    vision_tagline: "বড় লক্ষ্য, ছোট পদক্ষেপ।",
    faq_a_app_tour: "প্রথমবার ঢোকার সময় ট্যুরটি একবার নিজে থেকেই খোলে। এটি শুরু হয় নিজের অংশগুলো দিয়ে – কোনো অংশে ট্যাপ করলে সরাসরি সেখানে চলে যাবেন – তারপর অ্যাপের প্রতিটি অংশ (হোম স্ক্রিন, AI সহকারী আর মেনুর প্রতিটি আইটেম) আর সেটিংসের পাঁচটি গ্রুপ দেখায়, প্রতিটির সংক্ষিপ্ত ব্যাখ্যাসহ, আর কয়েকটির ভেতরেও উঁকি দেয় (যেমন একটি নমুনা লক্ষ্যের পথ, ব্যাগ আর Google Calendar)। \"চালিয়ে যান\" এগিয়ে নেয়, \"ফিরে যান\" পেছনে নেয়, \"এই অংশটি বাদ দিন\" পরের অংশে নিয়ে যায় আর ✕ ট্যুর বন্ধ করে। যেকোনো সময় সেটিংস > সাহায্য ও ব্যবহার > অ্যাপ ট্যুর থেকে আবার দেখতে পারেন, আর আগের জায়গা থেকে চালিয়ে যেতে পারেন। \"চালিয়ে যান\" আর \"ফিরে যান\" সবসময় স্ক্রিনের নিচে একই জায়গায় থাকে, আর কম্পিউটারে কিবোর্ডের তীর-চিহ্নের কী-ও কাজ করে।",
