    apptour_s_notifications_text: "অনুস্মারক বিজ্ঞপ্তি ও সেগুলোর শব্দ। রিমাইন্ডারে '⏰ এখনও না' স্নুজের মতো কাজ করে: প্রতি 5 মিনিট পরপর আবার মনে করিয়ে দেয়।",
