    apptour_m_tables_link: "AI সহকারী স্বয়ংক্রিয়ভাবে টেবিল ডিজাইন করতে পারে।",
    apptour_m_tables_text: "ব্যক্তিগত টেবিল – উপহার, সিরিজ, তালিকা – টেক্সট, সংখ্যা, নির্বাচন, তারিখ ও ✓ কলামসহ (প্রিমিয়াম)।",
