    apptour_m_study_text: "আপনার ব্যাগ: জীবনের প্রতিটি দিকের জন্য একটি পকেট – ভেতরে খাতা, টেবিল আর কাজ।",
    apptour_m_vision_link: "কোনো মাইলফলকে 📅 সেটিকে ক্যালেন্ডারে রাখে; ছোট পদক্ষেপ আর দিনের চ্যালেঞ্জের কাজ আমার দিন-এ দেখা যায়, আর অগ্রগতি কোনো সংখ্যা বা আপনার ওজন অনুযায়ীও চলতে পারে।",
    apptour_m_vision_text: "আপনার লক্ষ্যগুলো ছোট পদক্ষেপের পথের মতো – আর আজকের পদক্ষেপগুলো একেবারে ওপরে। চলুন ভেতরে উঁকি দিই 👇",
    apptour_m_myweek_link: "Google Calendar-এর সাথে সিঙ্ক হয় (সেটিংস-এ)।",
    apptour_m_myweek_text: "মাসিক ক্যালেন্ডার, রিমাইন্ডারসহ পুনরাবৃত্ত সাপ্তাহিক কাজ, আর তারিখসহ সব ইভেন্ট। সাথে সপ্তাহের মিটিংগুলোর একটি কাগজের ডায়েরি 🤝।",
    apptour_m_newme_link: "সবকিছু দৈনিক খাবার ট্র্যাকার ও আমার দিন-এ গোনা হয়; ওজন ক্যালোরি ও ওজন পরিমাপ-এর সাথে শেয়ার করা হয়।",
    apptour_m_newme_text: "এক জাদুর খেলার জগতে 1,300 / 1,500 ক্যালোরির খাবার পরিকল্পনা: ✓ সহ আজকের মেনু, তিনভাবে বদল – মেনু থেকে, সংরক্ষিত খাবার থেকে, বা কী খেয়েছেন তা AI-কে লিখে, আর সে ক্যালোরি হিসাব করে দেয় – কেনাকাটার তালিকা, খাবারের রিমাইন্ডার এবং অর্জন, মাপ ও ছবিসহ অগ্রগতির যাত্রা। সঙ্গে 🏆 ২০টি চ্যালেঞ্জ – শেষে একটি উপহারসহ – আর সপ্তাহের চ্যালেঞ্জ।",
    apptour_ai_table_text: "প্রয়োজনীয় টেবিলের বর্ণনা দিন – AI এর কলামগুলো ডিজাইন করে (প্রিমিয়াম)।",
    apptour_ai_photo_link: "আমার রেসিপি-তে সংরক্ষিত হয়।",
    apptour_ai_photo_text: "লেখা রেসিপির ছবি তুলুন – AI আপনার জন্য নতুন রেসিপি পূরণ করে দেয়।",
    apptour_ai_schedule_link: "সেগুলো ক্যালেন্ডারে ও আমার দিন-এ দেখা যায়।",
    apptour_ai_schedule_text: "সহজ ভাষায় পরিকল্পনা বলুন, একবারের বা পুনরাবৃত্ত – সেগুলো সরাসরি ক্যালেন্ডারে চলে যায়।",
    apptour_ai_food_link: "সরাসরি দৈনিক খাবার ট্র্যাকার ও আজকের মোটে যোগ হয়।",
    apptour_ai_food_text: "কী খেয়েছেন লিখুন – ক্যালোরি অনুমান করে আপনার জন্য লগ করা হয়।",
    apptour_newme_short_text: "New Me খোলে – আজকের মেনু সরাসরি মূল স্ক্রিনেই।",
    apptour_ai_link: "এর উপরের ছোট 1 ব্যাজটি প্রতিদিনের 'আজ সবচেয়ে গুরুত্বপূর্ণ কী' রিমাইন্ডার।",
    apptour_ai_text: "সহজ ভাষায় লিখুন, বাকিটা আপনার সহকারী করবে: ক্যালোরি লেখা, পরিকল্পনা ক্যালেন্ডারে রাখা, ছবি থেকে রেসিপি পড়া আর টেবিল বানানো।",
    apptour_quicknote_link: "📝 ও 🛒 পুরো তালিকা খোলে; 🍎 দৈনিক খাবার ট্র্যাকার-এ একটি সংরক্ষিত খাবার লগ করে।",
    apptour_quicknote_text: "দ্রুত কিছু লিখে ফেলুন – নোট-এ অথবা সরাসরি কেনাকাটার তালিকায়।",
    apptour_routine_link: "একটি অভ্যাস স্বয়ংক্রিয়ভাবে ওয়ার্কআউট ট্র্যাকিং-এ একটি ওয়ার্কআউট লগ করতে পারে।",
    apptour_routine_text: "ঘণ্টা ধরে আপনার দৈনিক রুটিন, ট্যাবে ভাগ করা (বাচ্চা, পড়াশোনা, কাজ…)। অভ্যাস ও ধারাবাহিকতা গড়তে প্রতিদিন ✓ দিন; 📅 পুরো মাস দেখায়।",
    apptour_premium_text: "পুরো AI সহকারী, থিম, ফন্ট, আমার ব্যাগ আর আরও অনেক কিছু খুলে দেয়।",
    apptour_note_text: "পুরো সপ্তাহের জন্য একটি স্টিকি নোট। ভেতরের ⚙ গিয়ার 1–3 লাইনের চেকলিস্ট যোগ করে এবং রঙ ও ধরন বদলায়।",
    apptour_peek_link: "AI, ক্যালেন্ডার, লক্ষ্যের ধাপ আর Google Calendar-এর কাজ সব এখানে দেখা যায় – সঙ্গে আজকের ক্যালোরি 🔥 আর আপনার 🎯 মাসের লক্ষ্য।",
    apptour_peek_text: "আজকের সবকিছু এক জায়গায় – কাজ, মিটিং, রুটিন আর ছোট ছোট পদক্ষেপ একটি টাইমলাইনে। এখানেই ✓ দিন।",
    apptour_date_text: "মাসিক ক্যালেন্ডারে দ্রুত নজর দিতে এতে ট্যাপ করুন – আর সঙ্গে সঙ্গে কিছু যোগ করুন।",
    apptour_date_title: "তারিখ",
    apptour_menu_text: "বাকি সবকিছু মেনুতে, বিষয় অনুযায়ী অপেক্ষা করছে। এই যে বড়গুলো 👇",
    apptour_welcome_text: "প্রায় পাঁচ মিনিট: অ্যাপের প্রতিটি অংশ, তারপর সেটিংস। যেকোনো সময় থামুন, পরে আবার চালিয়ে যান।",
