    table_select_option_delete_title: "বিকল্প মুছুন",
    faq_a_other_manual_option: "যেখানেই বিকল্পের তালিকা থেকে বেছে নিতে হয়, সেখানে '✏️ অন্যান্য' বিকল্পটিও থাকে - সেটি বেছে নিয়ে ঠিক যা দরকার তা টাইপ করুন। বাছাই কলামযুক্ত টেবিলে (যেমন উপহারের টেবিলে 'সম্পর্ক'), ঘরটিতে ট্যাপ করুন, '✏️ অন্যান্য' বেছে নিন, মানটি টাইপ করুন (যেমন 'ভাইপো') এবং যোগ করুন-এ ট্যাপ করুন - এটি সেই কলামের নতুন বিকল্প হিসেবে সংরক্ষিত হয়, তাই পরের বার এটি আগে থেকেই তালিকায় থাকে। ওই তালিকায় প্রতিটি বিকল্পের পাশে থাকা ছোট × চিহ্নটি বিকল্পটিকে কলাম থেকে মুছে দেয়। টেবিলের আইকন বাছাই করার সময় অনেক আইকন থাকে (রঙিন স্টিকি নোটসহ)। সংরক্ষিত খাবারের বিভাগ, রেসিপির বিভাগ, পুনরাবৃত্ত খরচের বিভাগ (নতুন ব্যক্তিগত বিভাগ হিসেবে সংরক্ষিত হয়) এবং 'আমার লক্ষ্যসমূহ'-এর লক্ষ্যের বিভাগেও এটি একইভাবে কাজ করে।",
