    faq_a_new_me_tracking: "New Me-র ওপরে পরের মিশনে ট্যাপ করুন, তারপর ✓ খেয়েছি-তে, তাহলে পরের খাবারটি খাওয়া হয়েছে বলে চিহ্নিত হবে – প্রতিটি খাবারে ✓-সহ পুরো মেনু আছে “সারা দিন”-এ (পাশে), আর আজকের খাবার হোম স্ক্রিনের আমার দিন-এও দেখা যায় – সেখানে কোনো খাবারে ট্যাপ করলে (বা ওপরে মাউস রাখলে) ঠিক কী খেতে হবে তা দেখায়, ✓ আর বদলান-সহ। সবকিছু দৈনিক খাবার ট্র্যাকারের সঙ্গে সিঙ্ক থাকে: পরিকল্পনার খাবার, পানীয় আর অন্য কোথাও যোগ করা সবকিছু (যেমন দ্রুত যোগ থেকে একটা কফি) New Me আর আমার দিন-এ একসঙ্গে গোনা হয় – আগে লেখা কিছুই মুছে যায় না, আর ✓ সরালে শুধু New Me-র অংশটুকু সরে। আজকের সব খাবারে চিহ্ন পড়লে একটা ছোট উদযাপন হয়। “পানীয়”-তে দিনের পানীয় লিখুন – সব মিলিয়ে ~150 ক্যালরি পর্যন্ত, মানে প্রায় 3টি পানীয়, প্রতিটি ~50 ক্যালরি পর্যন্ত। শুধু পানীয়ের নাম লিখলেই AI নিজে থেকে ক্যালরি বসিয়ে দেয়। কফি/চায়ের দুই সারিতে “দুধ? কতটা?” ঘরও আছে (যেমন “একটু” বা “50 মিলি”), আর হিসাব আপডেট হয়; সংখ্যাটি যোগ করার আগে আর পরেও বদলানো যায়। নাম আর ক্যালরিসহ পানীয় পরের ধাপে যাওয়া মাত্রই নিজে থেকে সংরক্ষিত হয় – যোগ করুন-এ ট্যাপ করা ঐচ্ছিক। কোনো পানীয়ের পাশে ☆-এ ট্যাপ করলে সেটি নিয়মিত পানীয় হিসেবে সংরক্ষিত হয় – নিয়মিত পানীয়গুলো পানীয় কার্ডের ওপরে বোতাম হিসেবে দেখায়, আর এক ট্যাপে দিনে যোগ হয়। ⭐ একটা খাবারকে সংরক্ষিত খাবার হিসেবে রাখে। “দৈনিক টেবিল” ক্যালরি আর প্রোটিনসহ দেখায় কী খাওয়া হয়েছে। হোম স্ক্রিনের ওপরে ফোকাস মোডের পাশে ছোট 💎 এটি সরাসরি খোলে। ক্যালরি আর প্রোটিনের মান AI-এর অনুমান, তাতে ভুল থাকতে পারে। সবটা খাওয়া হয়নি? চিহ্নিত খাবারের নিচে “সবটা খাওয়া হয়নি?” পরিমাণের এক-চতুর্থাংশ, অর্ধেক বা তিন-চতুর্থাংশ বাদ দেয় – অথবা আপনি যা লেখেন, হিসাব করে – আর দিনের ক্যালরি আপডেট হয়।",
    faq_q_new_me_tracking: "New Me-তে ✓, বদল ও ক্যালরি কীভাবে কাজ করে?",
    faq_a_new_me_what: "New Me একটি আলাদা দৈনিক মেনু প্রোগ্রাম, যাতে দুটি তৈরি পরিকল্পনা আছে – 1,300 বা 1,500 ক্যালোরি – 2টি প্রধান খাবার ও 2টি হালকা খাবার দিয়ে, প্রতিটির জন্য 3টি বিকল্পসহ। এতে পুরো প্রিমিয়াম অন্তর্ভুক্ত। দাম: মাসে $11.99 (যেকোনো সময় বাতিল) অথবা একবার $99.99, আজীবন। মেনুর 💎 New Me থেকে খুলুন। শুরুর আগে একটি ছোট প্রশ্নাবলি আছে, যা একটি চিকিৎসা সংক্রান্ত দাবিত্যাগ দিয়ে শুরু হয় এবং সেটি গ্রহণ করতে হয়। প্রোগ্রামটি শুধু সাধারণ তথ্য এবং ডাক্তার বা ক্লিনিক্যাল ডায়েটিশিয়ানের বিকল্প নয়।",
