    faq_a_finance_cycle_day: "ডিফল্টভাবে আপনার বাজেট সারাংশ প্রতি ক্যালেন্ডার মাসের 1 তারিখে রিসেট হয়। যদি অন্য কোনো দিনে বেতন পান (ধরুন 10 তারিখে), তাহলে এখানে সেই দিনটি ঠিক করুন - তখন আপনার মাসিক সারাংশ, ইতিহাস ও লক্ষ্য বাজেট 1 তারিখ থেকে মাসের শেষ পর্যন্ত না চলে, সেই দিন থেকে পরের মাসের একই দিন পর্যন্ত চলবে।",
