    daily_focus_p6_d6_s1: "সম্মানের সঙ্গে ব্যক্তিগত উদযাপন আর প্রাপ্য বিশ্রামের জন্য জায়গা করে দেওয়া", daily_focus_p6_d6_s2: "কৃতজ্ঞতা, শক্তি আর গভীর তৃপ্তি নিয়ে পুরো বছরের সারসংক্ষেপ করা", daily_focus_p6_d6_s3: "কৌতূহল, আত্মবিশ্বাস আর এই পথের প্রতি ভালোবাসা নিয়ে সামনের দিকে তাকানো", daily_focus_p6_d6_s4: "নিজে সব উজাড় করে দিয়েছি জেনে গভীর প্রশান্তিতে ছেড়ে দেওয়া", daily_focus_p6_d6_s5: "পরবর্তী চক্রের জন্য নতুন আর সতেজ শক্তিতে ভরে ওঠা",
    daily_focus_p6_d7_s1: "জীবন উদযাপন, প্রশান্তি আর গভীর কৃতজ্ঞতার জন্য দিনটি উৎসর্গ করা", daily_focus_p6_d7_s2: "পূর্ণতা আর সম্পূর্ণ তৃপ্তির অনুভূতি থেকে ভেতরের নীরবতা শোনা", daily_focus_p6_d7_s3: "বৃদ্ধি, সাহস আর সাফল্যে ভরা পুরো একটা বছরের জন্য নিজেকে বাহবা দেওয়া", daily_focus_p6_d7_s4: "সব কিছু ছেড়ে দেওয়া আর স্বচ্ছ, শান্ত উপস্থিতি উপভোগ করা", daily_focus_p6_d7_s5: "এই যাত্রা জুড়ে নিজে যা হয়ে উঠেছি তার জন্য কৃতজ্ঞতা জানানো",
    faq_q_daily_focus_prompt: "আজ আমার করার সবচেয়ে গুরুত্বপূর্ণ কাজ কী, এটা জিজ্ঞেস করা ছোট রিমাইন্ডারটি কী?", faq_a_daily_focus_prompt: "এটি একটি প্রিমিয়াম দৈনিক রিমাইন্ডার: দিনে একবার AI সহায়কের আইকনে একটি ছোট “1” ব্যাজ দেখা যায়। ব্যাজে ট্যাপ করলে একটি বাবল খোলে যা জিজ্ঞেস করে আজ আপনার জন্য সবচেয়ে গুরুত্বপূর্ণ কী, আর সেখানেই সঙ্গে সঙ্গে 5টি তৈরি পরামর্শ দেখা যায় (প্রতিদিন বদলায়, সারা বছর ধরে বিভিন্ন থিমে ঘুরে ঘুরে আসে যাতে নতুন থাকে) সঙ্গে নিজের লেখার জন্য 'অন্যান্য' - একাধিক বেছে নিতে পারেন। যোগ করুন-এ ট্যাপ করুন, আর আপনার বাছাইগুলো 'আমার দিন'-এর উপরে ছোট রিমাইন্ডার ট্যাগ হিসেবে দেখা যাবে (এগুলো টিক দেওয়ার কাজ নয়)। ✕ দিয়ে বন্ধ করলে বা বাইরে ট্যাপ করলে ব্যাজটি অদৃশ্য না হয়ে দিনের বাকি সময়ের জন্য শুধু ফিকে হয়ে যায়। এটি ডিফল্টভাবে চালু থাকে, তবে সেটিংস > ব্যক্তিগতকরণ ও ক্যালেন্ডার-এ বন্ধ করতে পারেন। আজ সুবিধা হচ্ছে না? '🌙 আজ নয়' ট্যাপ করুন – ব্যাজটি কাল পর্যন্ত লুকিয়ে যায়, তারপর প্রশ্নটি স্বাভাবিকভাবে ফিরে আসে। পরামর্শগুলোর একটি আসে আপনার নিজের জীবন থেকে – মাসের লক্ষ্যের পরের ধাপ বা আজকের পড়া। প্রতিটি দিন নতুন করে শুরু হয়।",
